interface CalculationBreakdownProps {
  record: Pick<
    CommissionRecord,
    | 'service_price_cents'
    | 'tip_cents'
    | 'commission_cents'
    | 'tip_commission_cents'
    | 'total_cents'
    | 'calculation_notes'
    | 'rule_snapshot'
  >
}

export function CalculationBreakdown({ record }: CalculationBreakdownProps) {
  const snapshot = record.rule_snapshot as CommissionRuleSnapshot

  return (
    <div className="commission-preview">
      {snapshot.percentage != null && (
        <CalculationLine
          label={formatCurrency(record.service_price_cents)}
          operator="×"
          rhs={`${snapshot.percentage}%`}
          result={`= ${formatCurrency(record.commission_cents)}`}
          note="service commission"
        />
      )}
      {snapshot.flat_fee_cents != null && snapshot.percentage == null && (
        <CalculationLine
          label="Flat fee"
          result={formatCurrency(record.commission_cents)}
          note="service commission"
        />
      )}
      {snapshot.flat_fee_cents != null && snapshot.percentage != null && (
        <CalculationLine
          label={`+ ${formatCurrency(snapshot.flat_fee_cents)}`}
          result="flat fee included above"
          note=""
        />
      )}
      {record.tip_commission_cents > 0 && (
        <CalculationLine
          label={formatCurrency(record.tip_cents)}
          operator="×"
          rhs={`${snapshot.tip_split_pct}%`}
          result={`= ${formatCurrency(record.tip_commission_cents)}`}
          note="tip commission"
        />
      )}
      <Separator className="my-2" />
      <div className="flex items-center justify-between">
        <span className="commission-preview-label">Total commission</span>
        <span className="commission-preview-total tabular-nums">
          {formatCurrency(record.total_cents)}
        </span>
      </div>
      {record.calculation_notes && (
        <p className="text-[10px] text-amber-400/80 mt-2">Note: {record.calculation_notes}</p>
      )}
    </div>
  )
}

import { format } from 'date-fns'
import { cn } from '@/lib/utils'
import type { CommissionRecord } from '@/lib/supabase/types'

interface StatusTimelineProps {
  record: Pick<
    CommissionRecord,
    'created_at' | 'approved_at' | 'cancelled_at' | 'status'
  > & { paid_at?: string | null }
}

export function StatusTimeline({ record }: StatusTimelineProps) {
  const steps = [
    {
      label: 'Created',
      at: record.created_at,
      done: true,
    },
    {
      label: 'Approved',
      at: record.approved_at,
      done: !!record.approved_at,
    },
    {
      label: record.status === 'cancelled' ? 'Cancelled' : 'Paid',
      at: record.cancelled_at ?? record.paid_at ?? null,
      done: !!record.cancelled_at || !!record.paid_at,
      isDestructive: !!record.cancelled_at,
    },
  ]

  return (
    <div className="relative pl-5">
      <div className="absolute left-[9px] top-2 bottom-2 w-px bg-border" />
      {steps.map((step, i) => (
        <div key={i} className="flex items-start gap-3 mb-3 last:mb-0">
          <div
            className={cn(
              'relative z-10 h-[18px] w-[18px] rounded-full border-2 flex items-center justify-center shrink-0 mt-0.5',
              step.done && !step.isDestructive
                ? 'border-primary bg-primary/20'
                : step.done && step.isDestructive
                  ? 'border-destructive bg-destructive/20'
                  : 'border-border bg-background',
            )}
          >
            {step.done && (
              <div
                className={cn(
                  'h-1.5 w-1.5 rounded-full',
                  step.isDestructive ? 'bg-destructive' : 'bg-primary',
                )}
              />
            )}
          </div>
          <div>
            <p
              className={cn(
                'text-sm font-medium',
                !step.done && 'text-muted-foreground',
                step.isDestructive && step.done && 'text-destructive',
              )}
            >
              {step.label}
            </p>
            {step.at && (
              <p className="text-xs text-muted-foreground tabular-nums">
                {format(new Date(step.at), 'MMM d, yyyy · h:mm a')}
              </p>
            )}
          </div>
        </div>
      ))}
    </div>
  )
}

'use client'

import { cn } from '@/lib/utils'

interface RuleTimelineBarProps {
  from: string
  until: string | null
  className?: string
}

export function RuleTimelineBar({ from, until, className }: RuleTimelineBarProps) {
  const today = new Date()
  const fromDate = new Date(from)
  const untilDate = until ? new Date(until) : null

  // 12-month window: 6 months before today, 6 months after
  const windowStart = new Date(today)
  windowStart.setMonth(windowStart.getMonth() - 6)
  const windowEnd = new Date(today)
  windowEnd.setMonth(windowEnd.getMonth() + 6)
  const windowSpan = windowEnd.getTime() - windowStart.getTime()

  const clamp = (val: number) => Math.max(0, Math.min(1, val))

  const fromPct = clamp((fromDate.getTime() - windowStart.getTime()) / windowSpan) * 100
  const untilPct = untilDate
    ? clamp((untilDate.getTime() - windowStart.getTime()) / windowSpan) * 100
    : 100
  const todayPct = clamp((today.getTime() - windowStart.getTime()) / windowSpan) * 100

  const isActive =
    fromDate <= today && (untilDate === null || untilDate >= today)
  const isPast = untilDate !== null && untilDate < today
  const isFuture = fromDate > today

  const segmentClass = isActive
    ? 'rule-timeline-active'
    : isPast
      ? 'rule-timeline-past'
      : isFuture
        ? 'rule-timeline-future'
        : 'rule-timeline-past'

  return (
    <div className={cn('relative w-full max-w-[200px]', className)}>
      {/* Track */}
      <div className="h-1 w-full rounded-full" style={{ background: 'oklch(22% 0.02 264)' }} />
      {/* Segment */}
      <div
        className={cn('rule-timeline-segment absolute top-0', segmentClass)}
        style={{
          left: `${fromPct}%`,
          width: `${Math.max(untilPct - fromPct, 2)}%`,
        }}
      />
      {/* Today marker */}
      <div
        className="absolute top-0 bottom-0 w-px bg-primary/60"
        style={{ left: `${todayPct}%` }}
      >
        <div
          className="absolute bottom-[-4px] left-[-2px] text-[8px] text-primary/60 leading-none"
          aria-hidden="true"
        >
          ▲
        </div>
      </div>
    </div>
  )
}

