import { formatCurrency } from '@/lib/utils'
import { toast } from 'sonner'
import { useQueryClient } from '@tanstack/react-query'

interface BulkApprovalFooterProps {
  selectedIds: string[]
  selectedTotalCents: number
  onClear: () => void
  canApprove: boolean
}

export function BulkApprovalFooter({
  selectedIds,
  selectedTotalCents,
  onClear,
  canApprove,
}: BulkApprovalFooterProps) {
  const [approveOpen, setApproveOpen] = useState(false)
  const [isApproving, setIsApproving] = useState(false)
  const queryClient = useQueryClient()
  const selectedCount = selectedIds.length

  if (selectedCount === 0) return null

  async function handleBulkApprove() {
    if (isApproving) return
    setIsApproving(true)
    try {
      const resp = await fetch('/api/commissions/records/approve', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ record_ids: selectedIds }),
      })
      const json = await resp.json()
      if (!resp.ok) throw new Error(json.error ?? 'Failed to approve')
      toast.success(`${json.approved_count ?? selectedCount} commissions approved`)
      onClear()
      await queryClient.invalidateQueries({ queryKey: ['commission-records'] })
      await queryClient.invalidateQueries({ queryKey: ['commission-dashboard'] })
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to approve commissions')
    } finally {
      setIsApproving(false)
      setApproveOpen(false)
    }
  }

  return (
    <>
      <div className="bulk-action-footer">
        <span className="text-sm font-medium tabular-nums text-foreground">
          {selectedCount} selected
        </span>
        <span className="text-xs text-muted-foreground tabular-nums">
          {formatCurrency(selectedTotalCents)} total
        </span>
        <div className="ml-auto flex items-center gap-2">
          <Button
            size="sm"
            onClick={() => setApproveOpen(true)}
            disabled={!canApprove || isApproving}
          >
            {isApproving ? (
              <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />
            ) : (
              <Check className="h-3.5 w-3.5 mr-1.5" />
            )}
            Approve selected
          </Button>
        </div>
        <Button
          variant="ghost"
          size="icon"
          className="h-7 w-7 text-muted-foreground hover:text-foreground shrink-0"
          onClick={onClear}
          aria-label="Clear selection"
        >
          <X className="h-3.5 w-3.5" />
        </Button>
      </div>

      <AlertDialog open={approveOpen} onOpenChange={setApproveOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Approve {selectedCount} commission records?</AlertDialogTitle>
            <AlertDialogDescription>
              This will approve {formatCurrency(selectedTotalCents)} total across {selectedCount}{' '}
              records. Approved commissions are included in the next payroll run.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Cancel</AlertDialogCancel>
            <AlertDialogAction onClick={handleBulkApprove} disabled={isApproving}>
              {isApproving && <Loader2 className="h-4 w-4 mr-1.5 animate-spin" />}
              Approve {selectedCount} records
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}

'use client'

import { useState } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from '@/components/ui/sheet'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Button } from '@/components/ui/button'
import { Separator } from '@/components/ui/separator'
import { Skeleton } from '@/components/ui/skeleton'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { Textarea } from '@/components/ui/textarea'
import { Label } from '@/components/ui/label'
import { Loader2, Check, RotateCcw, Flag, X, ExternalLink } from 'lucide-react'
import Link from 'next/link'
import { format } from 'date-fns'
import { formatCurrency, cn } from '@/lib/utils'
import { toast } from 'sonner'
import { CommissionStatusBadge } from './CommissionStatusBadge'
import { CalculationBreakdown } from './CalculationBreakdown'
import { StatusTimeline } from './StatusTimeline'
import { RaiseDisputeModal } from './RaiseDisputeModal'
import type { CommissionRecord } from '@/lib/supabase/types'
import type { CommissionRuleSnapshot } from '@/lib/supabase/types'

interface DetailRow {
  label: string
  value: React.ReactNode
}

function DetailRowComp({ label, value }: DetailRow) {
  return (
    <div className="flex items-start justify-between text-sm">
      <span className="text-muted-foreground text-xs shrink-0 w-16">{label}</span>
      <span className="text-right">{value}</span>
    </div>
  )
}

const MATCHED_BY_LABELS: Record<CommissionRuleSnapshot['matched_by'], string> = {
  service_specific: 'Service rule',
  catch_all: 'All services',
  artist_default: 'Artist default',
  none: 'No rule',
}

interface RecordDetailDrawerProps {
  recordId: string | null
  open: boolean
  onOpenChange: (open: boolean) => void
  currentMemberRole: string
  canApprove: boolean
  canManage: boolean
}

export function RecordDetailDrawer({
  recordId,
  open,
  onOpenChange,
  currentMemberRole,
  canApprove,
  canManage,
}: RecordDetailDrawerProps) {
  const [cancelOpen, setCancelOpen] = useState(false)
  const [cancelReason, setCancelReason] = useState('')
  const [isCancelling, setIsCancelling] = useState(false)
  const [isApproving, setIsApproving] = useState(false)
  const [isRecalculating, setIsRecalculating] = useState(false)
  const [disputeOpen, setDisputeOpen] = useState(false)
  const queryClient = useQueryClient()

  const { data, isLoading } = useQuery<{ data: CommissionRecord & { artists: { display_name: string; avatar_url: string | null } | null; services: { name: string } | null; bookings: { scheduled_at: string; tip_cents: number; clients: { first_name: string; last_name: string | null } | null } | null } }>({
    queryKey: ['commission-record', recordId],
    queryFn: () => fetch(`/api/commissions/records/${recordId}`).then((r) => r.json()),
    enabled: !!recordId && open,
    staleTime: 30_000,
  })

  const record = data?.data
  const snapshot = record?.rule_snapshot as CommissionRuleSnapshot | undefined
  const isArtist = currentMemberRole === 'artist'
  const isOwner = currentMemberRole === 'owner'
  const canRaiseDispute =
    !isArtist ? canManage : true // artist can raise on own records; owner/admin too
  const canCancel = isOwner && record && ['pending', 'approved'].includes(record.status)
  const canApproveThis = canApprove && record?.status === 'pending'
  const canRecalculate = canManage && record?.status === 'pending'

  async function handleApprove() {
    if (!record || isApproving) return
    setIsApproving(true)
    try {
      const resp = await fetch('/api/commissions/records/approve', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ record_ids: [record.id] }),
      })
      const json = await resp.json()
      if (!resp.ok) throw new Error(json.error ?? 'Failed to approve')
      toast.success('Commission approved')
      await queryClient.invalidateQueries({ queryKey: ['commission-records'] })
      await queryClient.invalidateQueries({ queryKey: ['commission-record', record.id] })
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to approve')
    } finally {
      setIsApproving(false)
    }
  }

  async function handleRecalculate() {
    if (!record || isRecalculating) return
    setIsRecalculating(true)
    try {
      const resp = await fetch(`/api/commissions/records/${record.id}/recalculate`, {
        method: 'POST',
      })
      const json = await resp.json()
      if (!resp.ok) throw new Error(json.error ?? 'Failed to recalculate')
      toast.success('Commission recalculated')
      await queryClient.invalidateQueries({ queryKey: ['commission-record', record.id] })
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to recalculate')
    } finally {
      setIsRecalculating(false)
    }
  }

  async function handleCancel() {
    if (!record || isCancelling || !cancelReason.trim()) return
    setIsCancelling(true)
    try {
      const resp = await fetch(`/api/commissions/records/${record.id}/cancel`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ reason: cancelReason }),
      })
      const json = await resp.json()
      if (!resp.ok) throw new Error(json.error ?? 'Failed to cancel')
      toast.success('Commission cancelled')
      setCancelOpen(false)
      setCancelReason('')
      await queryClient.invalidateQueries({ queryKey: ['commission-records'] })
      await queryClient.invalidateQueries({ queryKey: ['commission-record', record.id] })
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to cancel')
    } finally {
      setIsCancelling(false)
    }
  }

  return (
    <>
      <Sheet open={open} onOpenChange={onOpenChange}>
        <SheetContent className="w-full sm:max-w-[520px] flex flex-col overflow-hidden p-0">
          <SheetHeader className="px-6 py-4 border-b border-border shrink-0">
            {isLoading || !record ? (
              <div className="flex items-center justify-between">
                <div className="space-y-1">
                  <Skeleton className="h-5 w-40" />
                  <Skeleton className="h-3 w-28" />
                </div>
                <Skeleton className="h-5 w-20 rounded-full" />
              </div>
            ) : (
              <div className="flex items-center justify-between">
                <div>
                  <SheetTitle className="text-base font-semibold">Commission Record</SheetTitle>
                  <SheetDescription className="text-xs text-muted-foreground tabular-nums">
                    {record.bookings?.scheduled_at
                      ? format(new Date(record.bookings.scheduled_at), 'MMMM d, yyyy')
                      : '—'}
                  </SheetDescription>
                </div>
                <CommissionStatusBadge status={record.status} />
              </div>
            )}
          </SheetHeader>

          <ScrollArea className="flex-1">
            {isLoading || !record || !snapshot ? (
              <div className="p-6 space-y-4">
                {Array.from({ length: 6 }).map((_, i) => (
                  <Skeleton key={i} className="h-4 w-full" />
                ))}
              </div>
            ) : (
              <>
                {/* Booking section */}
                <div className="px-6 py-4 border-b border-border/50">
                  <h3 className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wide mb-3">
                    Booking
                  </h3>
                  <div className="space-y-2">
                    <DetailRowComp
                      label="Artist"
                      value={
                        <div className="flex items-center gap-1.5">
                          <Avatar className="h-5 w-5">
                            <AvatarImage src={record.artists?.avatar_url ?? undefined} />
                            <AvatarFallback className="text-[9px]">
                              {record.artists?.display_name.slice(0, 2).toUpperCase()}
                            </AvatarFallback>
                          </Avatar>
                          <span className="text-sm">{record.artists?.display_name}</span>
                        </div>
                      }
                    />
                    <DetailRowComp
                      label="Client"
                      value={
                        record.bookings?.clients
                          ? `${record.bookings.clients.first_name} ${record.bookings.clients.last_name ?? ''}`.trim()
                          : '—'
                      }
                    />
                    <DetailRowComp label="Service" value={record.services?.name ?? '—'} />
                    <DetailRowComp
                      label="Date"
                      value={
                        record.bookings?.scheduled_at
                          ? format(new Date(record.bookings.scheduled_at), 'MMM d, yyyy · h:mm a')
                          : '—'
                      }
                    />
                    <DetailRowComp
                      label="Price"
                      value={
                        <span className="tabular-nums">
                          {formatCurrency(record.service_price_cents)}
                        </span>
                      }
                    />
                    {(record.bookings?.tip_cents ?? 0) > 0 && (
                      <DetailRowComp
                        label="Tip"
                        value={
                          <span className="tabular-nums">
                            {formatCurrency(record.bookings!.tip_cents)}
                          </span>
                        }
                      />
                    )}
                  </div>
                  <Button
                    variant="link"
                    size="sm"
                    className="h-auto p-0 mt-2 text-xs text-muted-foreground hover:text-primary"
                    asChild
                  >
                    <Link href={`/appointments/${record.booking_id}`}>
                      View appointment <ExternalLink className="h-3 w-3 ml-1" />
                    </Link>
                  </Button>
                </div>

                {/* Rule snapshot */}
                <div className="px-6 py-4 border-b border-border/50">
                  <h3 className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wide mb-3">
                    Rule Applied
                  </h3>
                  <div className="space-y-2">
                    <DetailRowComp
                      label="Type"
                      value={
                        <span
                          className={cn(
                            `pill-rule-${snapshot.matched_by}`,
                            'inline-flex h-5 rounded-full px-2 text-[10px] font-medium items-center',
                          )}
                        >
                          {MATCHED_BY_LABELS[snapshot.matched_by]}
                        </span>
                      }
                    />
                    {snapshot.percentage != null && (
                      <DetailRowComp
                        label="Rate"
                        value={<span className="tabular-nums">{snapshot.percentage}%</span>}
                      />
                    )}
                    {snapshot.flat_fee_cents != null && (
                      <DetailRowComp
                        label="Flat fee"
                        value={
                          <span className="tabular-nums">
                            {formatCurrency(snapshot.flat_fee_cents)}
                          </span>
                        }
                      />
                    )}
                    <DetailRowComp
                      label="Tip split"
                      value={
                        <span className="tabular-nums">{snapshot.tip_split_pct ?? 100}%</span>
                      }
                    />
                    {snapshot.recalculated_at && (
                      <DetailRowComp
                        label="Recalc."
                        value={
                          <span className="text-xs text-amber-400 tabular-nums">
                            {format(new Date(snapshot.recalculated_at), 'MMM d, yyyy')}
                          </span>
                        }
                      />
                    )}
                  </div>
                </div>

                {/* Calculation */}
                <div className="px-6 py-4 border-b border-border/50">
                  <h3 className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wide mb-3">
                    Calculation
                  </h3>
                  <CalculationBreakdown record={record} />
                </div>

                {/* Timeline */}
                <div className="px-6 py-4 border-b border-border/50">
                  <h3 className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wide mb-3">
                    Timeline
                  </h3>
                  <StatusTimeline record={record} />
                </div>
              </>
            )}
          </ScrollArea>

          {/* Actions footer */}
          {record && (
            <div className="px-6 py-4 border-t border-border shrink-0">
              <div className="flex flex-wrap items-center gap-2">
                {canApproveThis && (
                  <Button size="sm" onClick={handleApprove} disabled={isApproving}>
                    {isApproving ? (
                      <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />
                    ) : (
                      <Check className="h-3.5 w-3.5 mr-1.5" />
                    )}
                    Approve
                  </Button>
                )}
                {canRecalculate && !isArtist && (
                  <Button
                    size="sm"
                    variant="outline"
                    onClick={handleRecalculate}
                    disabled={isRecalculating}
                  >
                    {isRecalculating ? (
                      <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />
                    ) : (
                      <RotateCcw className="h-3.5 w-3.5 mr-1.5" />
                    )}
                    Recalculate
                  </Button>
                )}
                {canRaiseDispute &&
                  record.status !== 'cancelled' &&
                  record.status !== 'disputed' && (
                    <Button size="sm" variant="outline" onClick={() => setDisputeOpen(true)}>
                      <Flag className="h-3.5 w-3.5 mr-1.5" />
                      Raise dispute
                    </Button>
                  )}
                {canCancel && (
                  <Button
                    size="sm"
                    variant="ghost"
                    className="text-destructive hover:text-destructive ml-auto"
                    onClick={() => setCancelOpen(true)}
                  >
                    <X className="h-3.5 w-3.5 mr-1.5" />
                    Cancel
                  </Button>
                )}
              </div>
            </div>
          )}
        </SheetContent>
      </Sheet>

      {/* Cancel confirmation */}
      <AlertDialog open={cancelOpen} onOpenChange={setCancelOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this commission?</AlertDialogTitle>
            <AlertDialogDescription>
              Cancelling will void this commission record. If the record is already approved, a
              penalty adjustment will be created for your review.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <div className="space-y-1.5 px-1">
            <Label className="text-xs font-medium">Reason</Label>
            <Textarea
              value={cancelReason}
              onChange={(e) => setCancelReason(e.target.value)}
              placeholder="Why are you cancelling this commission?"
              className="resize-none h-20 text-sm"
              maxLength={500}
            />
          </div>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep commission</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleCancel}
              disabled={isCancelling || !cancelReason.trim()}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {isCancelling && <Loader2 className="h-4 w-4 mr-1.5 animate-spin" />}
              Cancel commission
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>

      {/* Raise dispute modal */}
      {record && (
        <RaiseDisputeModal
          open={disputeOpen}
          onOpenChange={setDisputeOpen}
          record={{
            id: record.id,
            total_cents: record.total_cents,
            service_name: record.services?.name ?? '—',
            booking_scheduled_at: record.bookings?.scheduled_at ?? record.created_at,
          }}
        />
      )}
    </>
  )
}

