84	────────────────────────────────────────────────────────── */
85	--color-bulk-footer-bg:     oklch(10% 0.02 264 / 0.96);
86	--color-bulk-footer-border: oklch(28% 0.04 264);
87	
88	/* ──────────────────────────────────────────────────────────
89	   COMMISSION RULE — effective date timeline
90	────────────────────────────────────────────────────────── */
