'use client'

import { useState } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import {
  Card,
  CardContent,
  CardHeader,
} from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import { Plus, Settings2, MoreHorizontal, Loader2 } from 'lucide-react'
import { format, parseISO, isAfter, isBefore } from 'date-fns'
import { cn } from '@/lib/utils'
import { toast } from 'sonner'
import { RuleTimelineBar } from './RuleTimelineBar'
import { RuleEditorDrawer } from './RuleEditorDrawer'
import type { CommissionRule } from '@/lib/supabase/types'

interface ArtistWithRules {
  artist_id: string
  artist_name: string
  avatar_url: string | null
  rules: RuleWithService[]
}

interface RuleWithService extends CommissionRule {
  services: { name: string } | null
  artists: { display_name: string; avatar_url: string | null } | null
}

interface RulesListProps {
  canManage: boolean
  isArtist: boolean
}

function describeRule(rule: CommissionRule): string {
  const parts: string[] = []
  if (rule.percentage != null) parts.push(`${rule.percentage}%`)
  if (rule.flat_fee_cents != null) parts.push(`$${(rule.flat_fee_cents / 100).toFixed(0)} flat`)
  return parts.join(' + ') || 'No commission'
}

function isRuleActive(rule: CommissionRule): boolean {
  const now = new Date()
  const from = parseISO(rule.effective_from)
  if (isBefore(now, from)) return false
  if (rule.effective_until) {
    const until = parseISO(rule.effective_until)
    if (isAfter(now, until)) return false
  }
  return true
}

export function RulesList({ canManage, isArtist }: RulesListProps) {
  const [editorOpen, setEditorOpen] = useState(false)
  const [editingRule, setEditingRule] = useState<RuleWithService | null>(null)
  const [expireOpen, setExpireOpen] = useState(false)
  const [expiringRule, setExpiringRule] = useState<RuleWithService | null>(null)
  const [isExpiring, setIsExpiring] = useState(false)
  const queryClient = useQueryClient()

  const { data, isLoading } = useQuery<{ data: RuleWithService[] }>({
    queryKey: ['commission-rules'],
    queryFn: () => fetch('/api/commissions/rules').then((r) => r.json()),
    staleTime: 60_000,
  })

  const rules = data?.data ?? []

  // Group rules by artist
  const grouped: ArtistWithRules[] = Object.values(
    rules.reduce<Record<string, ArtistWithRules>>((acc, rule) => {
      if (!acc[rule.artist_id]) {
        acc[rule.artist_id] = {
          artist_id: rule.artist_id,
          artist_name: rule.artists?.display_name ?? 'Unknown Artist',
          avatar_url: rule.artists?.avatar_url ?? null,
          rules: [],
        }
      }
      acc[rule.artist_id].rules.push(rule)
      return acc
    }, {}),
  ).sort((a, b) => a.artist_name.localeCompare(b.artist_name))

  async function handleExpireRule() {
    if (!expiringRule || isExpiring) return
    setIsExpiring(true)
    try {
      const yesterday = new Date()
      yesterday.setDate(yesterday.getDate() - 1)
      const resp = await fetch(`/api/commissions/rules/${expiringRule.id}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ effective_until: yesterday.toISOString().split('T')[0] }),
      })
      const json = await resp.json()
      if (!resp.ok) throw new Error(json.error ?? 'Failed to expire rule')
      toast.success('Rule expired')
      setExpireOpen(false)
      setExpiringRule(null)
      await queryClient.invalidateQueries({ queryKey: ['commission-rules'] })
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to expire rule')
    } finally {
      setIsExpiring(false)
    }
  }

  function openEditor(rule: RuleWithService | null) {
    setEditingRule(rule)
    setEditorOpen(true)
  }

  if (isLoading) {
    return (
      <div className="px-6 py-4 space-y-4">
        {Array.from({ length: 3 }).map((_, i) => (
          <Card key={i} className="shadow-soft">
            <CardHeader className="pb-3">
              <div className="flex items-center gap-2">
                <Skeleton className="h-6 w-6 rounded-full" />
                <Skeleton className="h-4 w-[120px]" />
              </div>
            </CardHeader>
            <CardContent className="space-y-4 pb-4">
              {Array.from({ length: 2 }).map((_, j) => (
                <div key={j} className="flex items-start justify-between">
                  <div className="space-y-1.5">
                    <Skeleton className="h-4 w-[200px]" />
                    <Skeleton className="h-3 w-[150px]" />
                    <Skeleton className="h-1.5 w-[200px] rounded-full" />
                  </div>
                  <Skeleton className="h-7 w-[60px] rounded-md" />
                </div>
              ))}
            </CardContent>
          </Card>
        ))}
      </div>
    )
  }

  if (rules.length === 0) {
    return (
      <>
        <div className="flex flex-col items-center justify-center py-16 px-6 text-center">
          <Settings2 className="h-10 w-10 text-muted-foreground/40 mb-4" />
          <p className="text-sm font-medium text-foreground mb-1">No commission rules set up</p>
          <p className="text-xs text-muted-foreground max-w-xs mb-4">
            Each artist uses their default rate (set on their profile) until you add a rule. Rules let
            you set per-service or time-bound commission structures.
          </p>
          {canManage && (
            <Button size="sm" onClick={() => openEditor(null)}>
              <Plus className="h-4 w-4 mr-1.5" />
              Add first rule
            </Button>
          )}
        </div>
        <RuleEditorDrawer
          open={editorOpen}
          onOpenChange={setEditorOpen}
          rule={null}
        />
      </>
    )
  }

  return (
    <>
      {/* Read-only notice for artists */}
      {isArtist && (
        <p className="text-xs text-muted-foreground px-6 pb-3">
          Rules set by your studio owner. Contact them to request changes.
        </p>
      )}

      <div className="px-6 py-4 space-y-4">
        {/* New rule button — owner/admin only */}
        {canManage && (
          <div className="flex justify-end">
            <Button size="sm" variant="outline" className="h-8 text-xs" onClick={() => openEditor(null)}>
              <Plus className="h-3.5 w-3.5 mr-1" />
              New Rule
            </Button>
          </div>
        )}

        {grouped.map((group) => (
          <Card key={group.artist_id} className="shadow-soft">
            <CardHeader className="pb-3">
              <div className="flex items-center gap-2">
                <Avatar className="h-6 w-6">
                  <AvatarImage src={group.avatar_url ?? undefined} />
                  <AvatarFallback className="text-[10px]">
                    {group.artist_name.slice(0, 2).toUpperCase()}
                  </AvatarFallback>
                </Avatar>
                <span className="text-sm font-semibold">{group.artist_name}</span>
                <span className="inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium bg-muted text-muted-foreground">
                  Artist
                </span>
              </div>
            </CardHeader>
            <CardContent className="p-0">
              {group.rules.map((rule, idx) => {
                const active = isRuleActive(rule)
                const isLast = idx === group.rules.length - 1

                return (
                  <div
                    key={rule.id}
                    className={cn(
                      'flex items-start justify-between py-3 px-4',
                      !isLast && 'border-b border-border/40',
                    )}
                  >
                    {/* Left — rule details */}
                    <div className="flex flex-col gap-1 min-w-0">
                      <div className="flex items-center gap-2 flex-wrap">
                        <span
                          className={cn(
                            `pill-rule-${rule.service_id ? 'service_specific' : 'catch_all'}`,
                            'inline-flex h-5 rounded-full px-2 text-[10px] font-medium items-center',
                          )}
                        >
                          {rule.service_id ? 'Service rule' : 'All services'}
                        </span>
                        <span className="text-sm font-medium">
                          {rule.service_id ? (rule.services?.name ?? 'Unknown service') : 'All services'} —{' '}
                          {describeRule(rule)}
                          {rule.tip_split_pct < 100 && (
                            <span className="text-xs text-muted-foreground ml-1">
                              + {rule.tip_split_pct}% tip
                            </span>
                          )}
                          {rule.tip_split_pct === 100 && (
                            <span className="text-xs text-muted-foreground ml-1">
                              · artist keeps full tip
                            </span>
                          )}
                        </span>
                      </div>

                      <p className="text-xs text-muted-foreground tabular-nums">
                        {format(parseISO(rule.effective_from), 'MMM d, yyyy')} →{' '}
                        {rule.effective_until
                          ? format(parseISO(rule.effective_until), 'MMM d, yyyy')
                          : 'indefinite'}
                        {rule.priority > 0 && ` · Priority ${rule.priority}`}
                        {!active && (
                          <span className="ml-2 text-muted-foreground/60">(expired)</span>
                        )}
                      </p>

                      <RuleTimelineBar
                        from={parseISO(rule.effective_from)}
                        until={rule.effective_until ? parseISO(rule.effective_until) : null}
                      />
                    </div>

                    {/* Right — actions (owner/admin only) */}
                    {canManage && (
                      <div className="flex items-center gap-1 shrink-0 ml-4">
                        {active && (
                          <Button
                            variant="ghost"
                            size="sm"
                            className="h-7 text-xs"
                            onClick={() => openEditor(rule)}
                          >
                            Edit
                          </Button>
                        )}
                        <DropdownMenu>
                          <DropdownMenuTrigger asChild>
                            <Button variant="ghost" size="icon" className="h-7 w-7">
                              <MoreHorizontal className="h-3.5 w-3.5" />
                            </Button>
                          </DropdownMenuTrigger>
                          <DropdownMenuContent align="end">
                            {active && (
                              <DropdownMenuItem onClick={() => openEditor(rule)}>
                                Edit rule
                              </DropdownMenuItem>
                            )}
                            {active && (
                              <DropdownMenuItem
                                className="text-destructive"
                                onClick={() => {
                                  setExpiringRule(rule)
                                  setExpireOpen(true)
                                }}
                              >
                                Expire rule
                              </DropdownMenuItem>
                            )}
                          </DropdownMenuContent>
                        </DropdownMenu>
                      </div>
                    )}
                  </div>
                )
              })}
            </CardContent>
          </Card>
        ))}
      </div>

      {/* Rule editor drawer */}
      <RuleEditorDrawer
        open={editorOpen}
        onOpenChange={(o) => {
          setEditorOpen(o)
          if (!o) setEditingRule(null)
        }}
        rule={editingRule}
      />

      {/* Expire confirmation */}
      <AlertDialog open={expireOpen} onOpenChange={setExpireOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Expire this rule?</AlertDialogTitle>
            <AlertDialogDescription>
              The rule will be set to expire yesterday. New bookings will no longer use this rule.
              Existing commission records are not affected.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep rule</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleExpireRule}
              disabled={isExpiring}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {isExpiring && <Loader2 className="h-4 w-4 mr-1.5 animate-spin" />}
              Expire rule
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}

'use client'

import { useState, useEffect, useCallback } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import {
  Sheet,
  SheetContent,
  SheetDescription,
  SheetHeader,
  SheetTitle,
} from '@/components/ui/sheet'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Separator } from '@/components/ui/separator'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/components/ui/tooltip'
import { Loader2, Info } from 'lucide-react'
import { format, parseISO } from 'date-fns'
import { cn } from '@/lib/utils'
import { toast } from 'sonner'
import { CommissionPreview } from './CommissionPreview'
import type { CommissionRule } from '@/lib/supabase/types'

interface RuleWithService extends CommissionRule {
  services: { name: string } | null
  artists: { display_name: string; avatar_url: string | null } | null
}

interface RuleEditorDrawerProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  rule: RuleWithService | null
}

type StructureType = 'percentage' | 'flat' | 'both'
type ServiceScope = 'all' | 'specific'

interface FormState {
  artistId: string
  serviceScope: ServiceScope
  serviceId: string
  structureType: StructureType
  percentage: string
  flatFeeDollars: string
  tipSplitPct: number
  priority: string
  effectiveFrom: string
  effectiveUntil: string
}

function getInitialForm(rule: RuleWithService | null): FormState {
  if (!rule) {
    return {
      artistId: '',
      serviceScope: 'all',
      serviceId: '',
      structureType: 'percentage',
      percentage: '60',
      flatFeeDollars: '',
      tipSplitPct: 100,
      priority: '0',
      effectiveFrom: format(new Date(), 'yyyy-MM-dd'),
      effectiveUntil: '',
    }
  }

  let structureType: StructureType = 'percentage'
  if (rule.percentage != null && rule.flat_fee_cents != null) {
    structureType = 'both'
  } else if (rule.flat_fee_cents != null) {
    structureType = 'flat'
  }

  return {
    artistId: rule.artist_id,
    serviceScope: rule.service_id ? 'specific' : 'all',
    serviceId: rule.service_id ?? '',
    structureType,
    percentage: rule.percentage != null ? String(rule.percentage) : '',
    flatFeeDollars: rule.flat_fee_cents != null ? String(rule.flat_fee_cents / 100) : '',
    tipSplitPct: rule.tip_split_pct,
    priority: String(rule.priority),
    effectiveFrom: rule.effective_from.split('T')[0],
    effectiveUntil: rule.effective_until ? rule.effective_until.split('T')[0] : '',
  }
}

export function RuleEditorDrawer({ open, onOpenChange, rule }: RuleEditorDrawerProps) {
  const [form, setForm] = useState<FormState>(getInitialForm(rule))
  const [isPending, setIsPending] = useState(false)
  const queryClient = useQueryClient()

  // Reset form when rule changes
  useEffect(() => {
    setForm(getInitialForm(rule))
  }, [rule])

  const setField = useCallback(<K extends keyof FormState>(key: K, value: FormState[K]) => {
    setForm((prev) => ({ ...prev, [key]: value }))
  }, [])

  // Fetch artists for selector
  const { data: artistsData } = useQuery<{ data: Array<{ id: string; display_name: string; avatar_url: string | null }> }>({
    queryKey: ['artists-list'],
    queryFn: () => fetch('/api/artists').then((r) => r.json()),
    staleTime: 300_000,
    enabled: open,
  })

  // Fetch services for selector
  const { data: servicesData } = useQuery<{ data: Array<{ id: string; name: string }> }>({
    queryKey: ['services-list'],
    queryFn: () => fetch('/api/services').then((r) => r.json()),
    staleTime: 300_000,
    enabled: open && form.serviceScope === 'specific',
  })

  const artists = artistsData?.data ?? []
  const services = servicesData?.data ?? []

  // Derived preview rule
  const previewRule = {
    percentage:
      form.structureType === 'percentage' || form.structureType === 'both'
        ? parseFloat(form.percentage) || null
        : null,
    flat_fee_cents:
      form.structureType === 'flat' || form.structureType === 'both'
        ? Math.round(parseFloat(form.flatFeeDollars || '0') * 100) || null
        : null,
    tip_split_pct: form.tipSplitPct,
  }

  async function handleSave() {
    if (!form.artistId) {
      toast.error('Please select an artist')
      return
    }
    if (form.serviceScope === 'specific' && !form.serviceId) {
      toast.error('Please select a service')
      return
    }
    if (previewRule.percentage === null && previewRule.flat_fee_cents === null) {
      toast.error('Please enter a commission structure')
      return
    }

    setIsPending(true)
    try {
      const body = {
        artist_id: form.artistId,
        service_id: form.serviceScope === 'specific' ? form.serviceId : null,
        percentage: previewRule.percentage,
        flat_fee_cents: previewRule.flat_fee_cents,
        tip_split_pct: form.tipSplitPct,
        priority: parseInt(form.priority || '0', 10),
        effective_from: form.effectiveFrom,
        effective_until: form.effectiveUntil || null,
      }

      let resp: Response
      if (rule) {
        // Editing: expire old rule + create new via PATCH which handles atomic date swap
        resp = await fetch(`/api/commissions/rules/${rule.id}`, {
          method: 'PATCH',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(body),
        })
      } else {
        resp = await fetch('/api/commissions/rules', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify(body),
        })
      }

      const json = await resp.json()
      if (!resp.ok) throw new Error(json.error ?? 'Failed to save rule')

      toast.success(rule ? 'Rule updated' : 'Rule created')
      onOpenChange(false)
      await queryClient.invalidateQueries({ queryKey: ['commission-rules'] })
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to save rule')
    } finally {
      setIsPending(false)
    }
  }

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent className="w-full sm:max-w-[480px] flex flex-col overflow-hidden p-0">
        <SheetHeader className="px-6 py-4 border-b border-border shrink-0">
          <SheetTitle>{rule ? 'Edit Rule' : 'New Commission Rule'}</SheetTitle>
          {rule && (
            <SheetDescription className="text-xs text-muted-foreground">
              Editing an active rule creates a new version. The current rule will expire today.
            </SheetDescription>
          )}
        </SheetHeader>

        <ScrollArea className="flex-1">
          <div className="px-6 py-5 space-y-5">
            {/* 1. Artist */}
            <div className="space-y-1.5">
              <Label className="text-xs font-medium">
                Artist <span className="text-destructive">*</span>
              </Label>
              <Select
                value={form.artistId}
                onValueChange={(v) => setField('artistId', v)}
                disabled={!!rule}
              >
                <SelectTrigger>
                  <SelectValue placeholder="Select artist…" />
                </SelectTrigger>
                <SelectContent>
                  {artists.map((a) => (
                    <SelectItem key={a.id} value={a.id}>
                      <div className="flex items-center gap-2">
                        <Avatar className="h-5 w-5">
                          <AvatarImage src={a.avatar_url ?? undefined} />
                          <AvatarFallback className="text-[9px]">
                            {a.display_name.slice(0, 2).toUpperCase()}
                          </AvatarFallback>
                        </Avatar>
                        {a.display_name}
                      </div>
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>

            {/* 2. Service scope */}
            <div className="space-y-1.5">
              <Label className="text-xs font-medium">Applies to</Label>
              <RadioGroup
                value={form.serviceScope}
                onValueChange={(v) => setField('serviceScope', v as ServiceScope)}
                className="flex gap-3"
              >
                <div className="flex items-center gap-1.5">
                  <RadioGroupItem value="all" id="scope-all" />
                  <Label htmlFor="scope-all" className="text-sm font-normal cursor-pointer">
                    All services
                  </Label>
                </div>
                <div className="flex items-center gap-1.5">
                  <RadioGroupItem value="specific" id="scope-specific" />
                  <Label htmlFor="scope-specific" className="text-sm font-normal cursor-pointer">
                    Specific service
                  </Label>
                </div>
              </RadioGroup>
              {form.serviceScope === 'specific' && (
                <Select
                  value={form.serviceId}
                  onValueChange={(v) => setField('serviceId', v)}
                >
                  <SelectTrigger className="mt-1.5">
                    <SelectValue placeholder="Select service…" />
                  </SelectTrigger>
                  <SelectContent>
                    {services.map((s) => (
                      <SelectItem key={s.id} value={s.id}>
                        {s.name}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              )}
            </div>

            {/* 3. Commission structure */}
            <div className="space-y-2">
              <Label className="text-xs font-medium">Commission structure</Label>
              <RadioGroup
                value={form.structureType}
                onValueChange={(v) => setField('structureType', v as StructureType)}
                className="space-y-2"
              >
                {(
                  [
                    { value: 'percentage', label: 'Percentage of service price' },
                    { value: 'flat', label: 'Flat fee (fixed amount)' },
                    { value: 'both', label: 'Percentage + flat fee' },
                  ] as const
                ).map((opt) => (
                  <label
                    key={opt.value}
                    className="flex items-center gap-2.5 p-3 rounded-lg border border-border cursor-pointer hover:border-primary/40 transition-colors has-[:checked]:border-primary/60 has-[:checked]:bg-primary/[0.04]"
                  >
                    <RadioGroupItem value={opt.value} />
                    <span className="text-sm">{opt.label}</span>
                  </label>
                ))}
              </RadioGroup>

              <div className="flex gap-3 mt-3">
                {(form.structureType === 'percentage' || form.structureType === 'both') && (
                  <div className="flex-1 space-y-1">
                    <Label className="text-xs text-muted-foreground">Percentage</Label>
                    <div className="relative">
                      <Input
                        type="number"
                        min="0"
                        max="100"
                        step="0.5"
                        value={form.percentage}
                        onChange={(e) => setField('percentage', e.target.value)}
                        className="pr-7 tabular-nums"
                      />
                      <span className="absolute right-2.5 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">
                        %
                      </span>
                    </div>
                  </div>
                )}
                {(form.structureType === 'flat' || form.structureType === 'both') && (
                  <div className="flex-1 space-y-1">
                    <Label className="text-xs text-muted-foreground">Flat fee</Label>
                    <div className="relative">
                      <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">
                        $
                      </span>
                      <Input
                        type="number"
                        min="0"
                        step="1"
                        value={form.flatFeeDollars}
                        onChange={(e) => setField('flatFeeDollars', e.target.value)}
                        className="pl-6 tabular-nums"
                      />
                    </div>
                  </div>
                )}
              </div>
            </div>

            {/* 4. Tip split */}
            <div className="space-y-2">
              <div className="flex items-center justify-between">
                <Label className="text-xs font-medium">Tip split</Label>
                <span className="text-sm font-semibold tabular-nums text-primary">
                  {form.tipSplitPct}% to artist
                </span>
              </div>
              {/* Native range slider — styled to match design tokens */}
              <input
                type="range"
                min={0}
                max={100}
                step={5}
                value={form.tipSplitPct}
                onChange={(e) => setField('tipSplitPct', parseInt(e.target.value, 10))}
                className="w-full h-2 appearance-none rounded-full cursor-pointer"
                style={{
                  background: `linear-gradient(to right, oklch(62% 0.24 292) ${form.tipSplitPct}%, oklch(22% 0.02 264) ${form.tipSplitPct}%)`,
                }}
              />
              <div className="flex justify-between text-[10px] text-muted-foreground">
                <span>Studio keeps all</span>
                <span>Artist keeps all</span>
              </div>
            </div>

            {/* 5. Priority */}
            <div className="space-y-1.5">
              <Label className="text-xs font-medium flex items-center gap-1">
                Priority
                <Tooltip>
                  <TooltipTrigger asChild>
                    <Info className="h-3 w-3 text-muted-foreground cursor-help" />
                  </TooltipTrigger>
                  <TooltipContent side="right" className="max-w-[200px] text-xs">
                    When multiple rules match a booking, the higher priority wins. Service-specific
                    rules always beat catch-all rules regardless of priority.
                  </TooltipContent>
                </Tooltip>
              </Label>
              <Input
                type="number"
                min="0"
                max="100"
                value={form.priority}
                onChange={(e) => setField('priority', e.target.value)}
                className="w-[80px] tabular-nums"
              />
            </div>

            {/* 6. Effective dates */}
            <div className="flex gap-3">
              <div className="flex-1 space-y-1.5">
                <Label className="text-xs font-medium">
                  Effective from <span className="text-destructive">*</span>
                </Label>
                <Input
                  type="date"
                  value={form.effectiveFrom}
                  onChange={(e) => setField('effectiveFrom', e.target.value)}
                  className="tabular-nums"
                />
              </div>
              <div className="flex-1 space-y-1.5">
                <Label className="text-xs font-medium">
                  Effective until{' '}
                  <span className="text-[10px] text-muted-foreground">(blank = indefinite)</span>
                </Label>
                <Input
                  type="date"
                  value={form.effectiveUntil}
                  onChange={(e) => setField('effectiveUntil', e.target.value)}
                  placeholder="Indefinite"
                  className="tabular-nums"
                />
              </div>
            </div>

            <Separator className="my-4" />

            {/* Live commission preview */}
            <CommissionPreview
              price={50000}
              tip={5000}
              rule={previewRule}
            />
          </div>
        </ScrollArea>

        <div className="px-6 py-4 border-t border-border shrink-0 flex items-center justify-end gap-2">
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={isPending}>
            {isPending && <Loader2 className="h-4 w-4 mr-1.5 animate-spin" />}
            {rule ? 'Save changes' : 'Create rule'}
          </Button>
        </div>
      </SheetContent>
    </Sheet>
  )
}

'use client'

import { useState, useEffect } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog'
import { Button } from '@/components/ui/button'
import { Input } from '@/components/ui/input'
import { Label } from '@/components/ui/label'
import { Textarea } from '@/components/ui/textarea'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Loader2 } from 'lucide-react'
import { format } from 'date-fns'
import { formatCurrency, cn } from '@/lib/utils'
import { toast } from 'sonner'

type AdjustmentKind = 'bonus' | 'penalty' | 'correction' | 'guest_split' | 'other'

const KIND_LABELS: Record<AdjustmentKind, string> = {
  bonus: 'Bonus',
  penalty: 'Penalty',
  correction: 'Correction',
  guest_split: 'Guest split',
  other: 'Other',
}

interface ArtistOption {
  id: string
  display_name: string
  avatar_url: string | null
}

interface AdjustmentModalProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  /** Pre-select an artist — optional */
  preselectedArtistId?: string
}

interface FormState {
  artistId: string
  kind: AdjustmentKind
  isNegative: boolean
  amountDollars: string
  reason: string
  appliedDate: string
  /** Track if user explicitly picked a kind */
  kindManuallySet: boolean
}

export function AdjustmentModal({ open, onOpenChange, preselectedArtistId }: AdjustmentModalProps) {
  const [form, setForm] = useState<FormState>({
    artistId: preselectedArtistId ?? '',
    kind: 'bonus',
    isNegative: false,
    amountDollars: '',
    reason: '',
    appliedDate: format(new Date(), 'yyyy-MM-dd'),
    kindManuallySet: false,
  })
  const [isPending, setIsPending] = useState(false)
  const queryClient = useQueryClient()

  // Reset on open
  useEffect(() => {
    if (open) {
      setForm({
        artistId: preselectedArtistId ?? '',
        kind: 'bonus',
        isNegative: false,
        amountDollars: '',
        reason: '',
        appliedDate: format(new Date(), 'yyyy-MM-dd'),
        kindManuallySet: false,
      })
    }
  }, [open, preselectedArtistId])

  const { data: artistsData } = useQuery<{ data: ArtistOption[] }>({
    queryKey: ['artists-list'],
    queryFn: () => fetch('/api/artists').then((r) => r.json()),
    staleTime: 300_000,
    enabled: open,
  })

  const artists = artistsData?.data ?? []
  const selectedArtist = artists.find((a) => a.id === form.artistId)

  function toggleSign() {
    setForm((prev) => {
      const isNegative = !prev.isNegative
      // Auto-select kind based on sign unless manually set
      const kind = prev.kindManuallySet
        ? prev.kind
        : isNegative
        ? 'penalty'
        : 'bonus'
      return { ...prev, isNegative, kind }
    })
  }

  function setKind(k: AdjustmentKind) {
    setForm((prev) => ({ ...prev, kind: k, kindManuallySet: true }))
  }

  const amountCents = Math.round(parseFloat(form.amountDollars || '0') * 100)
  const signedCents = form.isNegative ? -amountCents : amountCents

  const isValid =
    form.artistId.length > 0 &&
    amountCents > 0 &&
    form.reason.trim().length > 0

  async function handleSave() {
    if (!isValid || isPending) return
    setIsPending(true)
    try {
      const resp = await fetch('/api/commissions/adjustments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          artist_id: form.artistId,
          kind: form.kind,
          amount_cents: signedCents,
          reason: form.reason,
          applied_at: new Date(form.appliedDate).toISOString(),
        }),
      })
      const json = await resp.json()
      if (!resp.ok) throw new Error(json.error ?? 'Failed to add adjustment')
      toast.success('Adjustment added')
      onOpenChange(false)
      await queryClient.invalidateQueries({ queryKey: ['commission-adjustments'] })
      await queryClient.invalidateQueries({ queryKey: ['commission-dashboard'] })
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to add adjustment')
    } finally {
      setIsPending(false)
    }
  }

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[460px]">
        <DialogHeader>
          <DialogTitle>Add Adjustment</DialogTitle>
          <DialogDescription className="text-xs">
            Manually add a bonus, penalty, or correction to an artist&apos;s commission.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-4 py-2">
          {/* Artist */}
          <div className="space-y-1.5">
            <Label className="text-xs font-medium">
              Artist <span className="text-destructive">*</span>
            </Label>
            <Select
              value={form.artistId}
              onValueChange={(v) => setForm((prev) => ({ ...prev, artistId: v }))}
            >
              <SelectTrigger>
                <SelectValue placeholder="Select artist…" />
              </SelectTrigger>
              <SelectContent>
                {artists.map((a) => (
                  <SelectItem key={a.id} value={a.id}>
                    <div className="flex items-center gap-2">
                      <Avatar className="h-5 w-5">
                        <AvatarImage src={a.avatar_url ?? undefined} />
                        <AvatarFallback className="text-[9px]">
                          {a.display_name.slice(0, 2).toUpperCase()}
                        </AvatarFallback>
                      </Avatar>
                      {a.display_name}
                    </div>
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Kind */}
          <div className="space-y-1.5">
            <Label className="text-xs font-medium">
              Kind <span className="text-destructive">*</span>
            </Label>
            <RadioGroup
              value={form.kind}
              onValueChange={(v) => setKind(v as AdjustmentKind)}
              className="grid grid-cols-3 gap-2"
            >
              {(Object.keys(KIND_LABELS) as AdjustmentKind[]).map((k) => (
                <label
                  key={k}
                  className="flex items-center gap-1.5 p-2.5 rounded-lg border border-border cursor-pointer text-xs hover:border-primary/40 has-[:checked]:border-primary/60 has-[:checked]:bg-primary/[0.04]"
                >
                  <RadioGroupItem value={k} />
                  {KIND_LABELS[k]}
                </label>
              ))}
            </RadioGroup>
          </div>

          {/* Amount */}
          <div className="space-y-1.5">
            <Label className="text-xs font-medium">
              Amount <span className="text-destructive">*</span>
            </Label>
            <div className="flex items-center gap-2">
              <Button
                type="button"
                variant="outline"
                size="sm"
                className={cn(
                  'w-8 h-9 shrink-0 font-bold tabular-nums',
                  form.isNegative
                    ? 'text-destructive border-destructive/40'
                    : 'text-[oklch(58%_0.18_145)] border-[oklch(58%_0.18_145)/40]',
                )}
                onClick={toggleSign}
              >
                {form.isNegative ? '−' : '+'}
              </Button>
              <div className="relative flex-1">
                <span className="absolute left-2.5 top-1/2 -translate-y-1/2 text-xs text-muted-foreground">
                  $
                </span>
                <Input
                  type="number"
                  min="0"
                  step="0.01"
                  value={form.amountDollars}
                  onChange={(e) =>
                    setForm((prev) => ({ ...prev, amountDollars: e.target.value }))
                  }
                  className={cn('pl-6 tabular-nums', form.isNegative && 'text-destructive')}
                  placeholder="0.00"
                />
              </div>
            </div>
            <p className="text-[10px] text-muted-foreground">
              Penalty = negative (deducts from artist). Bonus = positive (adds to artist).
            </p>
          </div>

          {/* Reason */}
          <div className="space-y-1.5">
            <Label className="text-xs font-medium">
              Reason <span className="text-destructive">*</span>
            </Label>
            <Textarea
              value={form.reason}
              onChange={(e) => setForm((prev) => ({ ...prev, reason: e.target.value }))}
              placeholder="Briefly explain this adjustment…"
              className="resize-none h-20 text-sm"
              maxLength={500}
            />
            <p className="text-[10px] text-muted-foreground text-right tabular-nums">
              {form.reason.length}/500
            </p>
          </div>

          {/* Applied date */}
          <div className="space-y-1.5">
            <Label className="text-xs font-medium">Applied date</Label>
            <Input
              type="date"
              value={form.appliedDate}
              onChange={(e) => setForm((prev) => ({ ...prev, appliedDate: e.target.value }))}
              className="tabular-nums"
            />
          </div>

          {/* Preview */}
          {form.artistId && amountCents > 0 && (
            <div className="commission-preview">
              <p className="commission-preview-label mb-1">Preview</p>
              <p className="text-sm text-foreground">
                This will{' '}
                <span
                  className={cn(
                    'font-semibold',
                    form.isNegative
                      ? 'text-destructive'
                      : 'text-[oklch(58%_0.18_145)]',
                  )}
                >
                  {form.isNegative ? 'deduct' : 'add'}
                </span>{' '}
                <span className="tabular-nums font-semibold">
                  {formatCurrency(amountCents)}
                </span>{' '}
                {form.isNegative ? 'from' : 'to'}{' '}
                <span className="font-semibold">
                  {selectedArtist?.display_name ?? '—'}
                </span>
                &apos;s next payout.
              </p>
            </div>
          )}
        </div>

        <DialogFooter>
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button onClick={handleSave} disabled={isPending || !isValid}>
            {isPending && <Loader2 className="h-4 w-4 mr-1.5 animate-spin" />}
            Add adjustment
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  )
}

'use client'

import { useState } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from '@/components/ui/alert-dialog'
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/components/ui/tooltip'
import { Plus, SlidersHorizontal, MoreHorizontal, Loader2 } from 'lucide-react'
import { format, parseISO } from 'date-fns'
import { formatCurrency, cn } from '@/lib/utils'
import { toast } from 'sonner'
import { AdjustmentModal } from './AdjustmentModal'

type AdjustmentKind = 'bonus' | 'penalty' | 'correction' | 'guest_split' | 'other'
type AdjustmentStatus = 'pending' | 'approved' | 'cancelled'

interface AdjustmentRow {
  id: string
  artist_id: string
  amount_cents: number
  kind: AdjustmentKind
  reason: string
  applied_at: string
  status: AdjustmentStatus
  artists: { display_name: string; avatar_url: string | null } | null
}

interface AdjustmentsListProps {
  from: string
  to: string
  canManage: boolean
  isArtist: boolean
}

const KIND_BADGE_MAP: Record<AdjustmentKind, string> = {
  bonus: 'badge-adj-bonus',
  penalty: 'badge-adj-penalty',
  correction: 'badge-adj-correction',
  guest_split: 'badge-adj-guest-split',
  other: 'badge-adj-other',
}

const KIND_LABELS: Record<AdjustmentKind, string> = {
  bonus: 'Bonus',
  penalty: 'Penalty',
  correction: 'Correction',
  guest_split: 'Guest split',
  other: 'Other',
}

export function AdjustmentsList({ from, to, canManage, isArtist }: AdjustmentsListProps) {
  const [modalOpen, setModalOpen] = useState(false)
  const [cancelOpen, setCancelOpen] = useState(false)
  const [cancellingId, setCancellingId] = useState<string | null>(null)
  const [isCancelling, setIsCancelling] = useState(false)
  const queryClient = useQueryClient()

  const { data, isLoading } = useQuery<{ data: AdjustmentRow[] }>({
    queryKey: ['commission-adjustments', from, to],
    queryFn: () =>
      fetch(`/api/commissions/adjustments?from=${from}&to=${to}`).then((r) => r.json()),
    staleTime: 30_000,
  })

  const adjustments = data?.data ?? []

  async function handleCancel() {
    if (!cancellingId || isCancelling) return
    setIsCancelling(true)
    try {
      const resp = await fetch(`/api/commissions/adjustments/${cancellingId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'cancelled' }),
      })
      const json = await resp.json()
      if (!resp.ok) throw new Error(json.error ?? 'Failed to cancel adjustment')
      toast.success('Adjustment cancelled')
      setCancelOpen(false)
      setCancellingId(null)
      await queryClient.invalidateQueries({ queryKey: ['commission-adjustments'] })
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to cancel adjustment')
    } finally {
      setIsCancelling(false)
    }
  }

  if (isLoading) {
    return (
      <div className="px-6 py-4 space-y-2">
        <div className="flex gap-2 pb-3 border-b border-border">
          <Skeleton className="h-8 w-[140px] rounded-md" />
          <Skeleton className="h-8 w-[200px] ml-auto rounded-md" />
        </div>
        {Array.from({ length: 5 }).map((_, i) => (
          <div
            key={i}
            className="flex items-center gap-4 py-3 border-b border-border/50"
            style={{ animationDelay: `${i * 40}ms`, animationFillMode: 'both' }}
          >
            <Skeleton className="h-4 w-[80px]" />
            <Skeleton className="h-6 w-6 rounded-full" />
            <Skeleton className="h-4 w-[100px]" />
            <Skeleton className="h-5 w-[80px] rounded-full" />
            <Skeleton className="h-4 w-[60px] ml-auto" />
            <Skeleton className="h-5 w-[80px] rounded-full" />
          </div>
        ))}
      </div>
    )
  }

  if (adjustments.length === 0) {
    return (
      <>
        <div className="flex flex-col items-center justify-center py-16 px-6 text-center">
          <SlidersHorizontal className="h-10 w-10 text-muted-foreground/40 mb-4" />
          <p className="text-sm font-medium text-foreground mb-1">No adjustments</p>
          <p className="text-xs text-muted-foreground max-w-xs mb-4">
            Use adjustments to record bonuses, penalties, corrections, or guest splits that fall
            outside the normal commission calculation.
          </p>
          {canManage && (
            <Button size="sm" onClick={() => setModalOpen(true)}>
              <Plus className="h-4 w-4 mr-1.5" />
              Add adjustment
            </Button>
          )}
        </div>
        <AdjustmentModal open={modalOpen} onOpenChange={setModalOpen} />
      </>
    )
  }

  return (
    <>
      <div className="px-6 py-3 border-b border-border flex items-center justify-between">
        <span className="text-xs text-muted-foreground tabular-nums">
          {adjustments.length} adjustment{adjustments.length !== 1 ? 's' : ''}
        </span>
        {canManage && (
          <Button size="sm" variant="outline" className="h-8 text-xs" onClick={() => setModalOpen(true)}>
            <Plus className="h-3.5 w-3.5 mr-1" />
            Add Adjustment
          </Button>
        )}
      </div>

      <Table>
        <TableHeader>
          <TableRow className="hover:bg-transparent">
            <TableHead className="text-xs">Date</TableHead>
            {!isArtist && <TableHead className="text-xs">Artist</TableHead>}
            <TableHead className="text-xs">Kind</TableHead>
            <TableHead className="text-right text-xs">Amount</TableHead>
            <TableHead className="text-xs">Reason</TableHead>
            <TableHead className="text-xs">Status</TableHead>
            {canManage && <TableHead className="w-10" />}
          </TableRow>
        </TableHeader>
        <TableBody>
          {adjustments.map((adj) => {
            const isPositive = adj.amount_cents >= 0
            return (
              <TableRow key={adj.id} className="hover:bg-muted/30 transition-colors">
                <TableCell className="text-sm tabular-nums">
                  {format(parseISO(adj.applied_at), 'MMM d, yy')}
                </TableCell>
                {!isArtist && (
                  <TableCell>
                    <div className="flex items-center gap-2">
                      <Avatar className="h-6 w-6 shrink-0">
                        <AvatarImage src={adj.artists?.avatar_url ?? undefined} />
                        <AvatarFallback className="text-[10px]">
                          {(adj.artists?.display_name ?? '?').slice(0, 2).toUpperCase()}
                        </AvatarFallback>
                      </Avatar>
                      <span className="text-sm truncate max-w-[120px]">
                        {adj.artists?.display_name ?? '—'}
                      </span>
                    </div>
                  </TableCell>
                )}
                <TableCell>
                  <span
                    className={cn(
                      KIND_BADGE_MAP[adj.kind],
                      'inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium',
                    )}
                  >
                    {KIND_LABELS[adj.kind]}
                  </span>
                </TableCell>
                <TableCell className="text-right">
                  <span
                    className={cn(
                      'tabular-nums font-semibold text-sm',
                      isPositive
                        ? 'text-[oklch(58%_0.18_145)]'
                        : 'text-[oklch(55%_0.22_27)]',
                    )}
                  >
                    {isPositive ? '+' : '−'}
                    {formatCurrency(Math.abs(adj.amount_cents))}
                  </span>
                </TableCell>
                <TableCell className="max-w-[160px]">
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="text-sm truncate block cursor-default" title={adj.reason}>
                        {adj.reason.length > 40 ? `${adj.reason.slice(0, 40)}…` : adj.reason}
                      </span>
                    </TooltipTrigger>
                    {adj.reason.length > 40 && (
                      <TooltipContent className="max-w-[240px] text-xs">{adj.reason}</TooltipContent>
                    )}
                  </Tooltip>
                </TableCell>
                <TableCell>
                  <span
                    className={cn(
                      'inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium',
                      adj.status === 'pending' && 'badge-commission-pending',
                      adj.status === 'approved' && 'badge-commission-approved',
                      adj.status === 'cancelled' && 'badge-commission-cancelled',
                    )}
                  >
                    {adj.status.charAt(0).toUpperCase() + adj.status.slice(1)}
                  </span>
                </TableCell>
                {canManage && (
                  <TableCell>
                    {adj.status === 'pending' && (
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="icon" className="h-7 w-7">
                            <MoreHorizontal className="h-3.5 w-3.5" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end">
                          <DropdownMenuItem
                            className="text-destructive"
                            onClick={() => {
                              setCancellingId(adj.id)
                              setCancelOpen(true)
                            }}
                          >
                            Cancel adjustment
                          </DropdownMenuItem>
                        </DropdownMenuContent>
                      </DropdownMenu>
                    )}
                  </TableCell>
                )}
              </TableRow>
            )
          })}
        </TableBody>
      </Table>

      <AdjustmentModal open={modalOpen} onOpenChange={setModalOpen} />

      <AlertDialog open={cancelOpen} onOpenChange={setCancelOpen}>
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Cancel this adjustment?</AlertDialogTitle>
            <AlertDialogDescription>
              Cancelling will void this adjustment. It will no longer be included in payroll
              calculations.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel>Keep adjustment</AlertDialogCancel>
            <AlertDialogAction
              onClick={handleCancel}
              disabled={isCancelling}
              className="bg-destructive text-destructive-foreground hover:bg-destructive/90"
            >
              {isCancelling && <Loader2 className="h-4 w-4 mr-1.5 animate-spin" />}
              Cancel adjustment
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  )
}

'use client'

import { useState } from 'react'
import { useQueryClient } from '@tanstack/react-query'
import {
  Sheet,
  SheetContent,
  SheetHeader,
  SheetTitle,
  SheetDescription,
} from '@/components/ui/sheet'
import { ScrollArea } from '@/components/ui/scroll-area'
import { Button } from '@/components/ui/button'
import { Textarea } from '@/components/ui/textarea'
import { Label } from '@/components/ui/label'
import { Separator } from '@/components/ui/separator'
import { RadioGroup, RadioGroupItem } from '@/components/ui/radio-group'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Loader2, CheckCircle2, Clock } from 'lucide-react'
import { format, parseISO } from 'date-fns'
import { formatCurrency, cn } from '@/lib/utils'
import { toast } from 'sonner'
import { CommissionStatusBadge } from './CommissionStatusBadge'

type DisputeStatus = 'open' | 'resolved' | 'dismissed'
type DisputeOutcome = 'upheld' | 'dismissed'

interface DisputeDetail {
  id: string
  reason: string
  status: DisputeStatus
  resolution_notes: string | null
  created_at: string
  raised_by_name: string
  raised_by_avatar: string | null
  commission_record: {
    id: string
    status: string
    total_cents: number
    service_price_cents: number
    tip_cents: number
    booking_scheduled_at: string
    artist_name: string
    client_name: string
    service_name: string
  } | null
}

interface DisputeResolutionDrawerProps {
  open: boolean
  onOpenChange: (open: boolean) => void
  dispute: DisputeDetail | null
  canResolve: boolean
  isArtist: boolean
}

function DetailRow({ label, value }: { label: string; value: React.ReactNode }) {
  return (
    <div className="flex items-start justify-between text-sm">
      <span className="text-muted-foreground text-xs shrink-0 w-20">{label}</span>
      <span className="text-right">{value}</span>
    </div>
  )
}

export function DisputeResolutionDrawer({
  open,
  onOpenChange,
  dispute,
  canResolve,
  isArtist,
}: DisputeResolutionDrawerProps) {
  const [outcome, setOutcome] = useState<DisputeOutcome | ''>('')
  const [resolutionNotes, setResolutionNotes] = useState('')
  const [isPending, setIsPending] = useState(false)
  const [resolved, setResolved] = useState(false)
  const queryClient = useQueryClient()

  const isOpen = dispute?.status === 'open'
  const shortId = dispute?.id.slice(0, 8).toUpperCase()

  async function handleResolve() {
    if (!dispute || !outcome || isPending) return
    if (outcome === 'upheld' && resolutionNotes.trim().length === 0) {
      toast.error('Resolution notes are required when upholding a dispute')
      return
    }
    setIsPending(true)
    try {
      const resp = await fetch(`/api/commissions/disputes/${dispute.id}/resolve`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          outcome,
          resolution_notes: resolutionNotes.trim() || null,
        }),
      })
      const json = await resp.json()
      if (!resp.ok) throw new Error(json.error ?? 'Failed to resolve dispute')
      toast.success('Dispute resolved')
      setResolved(true)
      await queryClient.invalidateQueries({ queryKey: ['commission-disputes'] })
      await queryClient.invalidateQueries({ queryKey: ['commission-records'] })
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to resolve dispute')
    } finally {
      setIsPending(false)
    }
  }

  function handleClose() {
    setResolved(false)
    setOutcome('')
    setResolutionNotes('')
    onOpenChange(false)
  }

  return (
    <Sheet open={open} onOpenChange={handleClose}>
      <SheetContent className="w-full sm:max-w-[500px] flex flex-col overflow-hidden p-0">
        <SheetHeader className="px-6 py-4 border-b border-border shrink-0">
          <div className="flex items-start justify-between">
            <div>
              <SheetTitle className="text-base font-semibold">
                Dispute #{shortId}
              </SheetTitle>
              {dispute && (
                <SheetDescription className="text-xs text-muted-foreground mt-0.5">
                  Raised by {dispute.raised_by_name} ·{' '}
                  {format(parseISO(dispute.created_at), 'MMM d, yyyy')}
                </SheetDescription>
              )}
            </div>
            {dispute && (
              <span
                className={cn(
                  `badge-dispute-${dispute.status}`,
                  'inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium shrink-0 mt-1',
                )}
              >
                {dispute.status.charAt(0).toUpperCase() + dispute.status.slice(1)}
              </span>
            )}
          </div>
        </SheetHeader>

        {resolved ? (
          /* Post-resolution success state */
          <div className="flex-1 flex flex-col items-center justify-center px-6 py-12 text-center">
            <div className="h-12 w-12 rounded-full bg-[oklch(58%_0.18_145/0.15)] flex items-center justify-center mb-4">
              <CheckCircle2 className="h-6 w-6 text-[oklch(58%_0.18_145)]" />
            </div>
            <p className="text-sm font-semibold mb-1">Dispute resolved</p>
            <p className="text-xs text-muted-foreground max-w-xs">
              Outcome:{' '}
              <span className="font-medium">
                {outcome === 'upheld' ? 'Upheld — record reset to pending' : 'Dismissed — record restored to approved'}
              </span>
            </p>
            {resolutionNotes && (
              <p className="text-xs text-muted-foreground mt-2 max-w-xs">
                &ldquo;{resolutionNotes}&rdquo;
              </p>
            )}
            <Button className="mt-6" variant="outline" onClick={handleClose}>
              Close
            </Button>
          </div>
        ) : (
          <ScrollArea className="flex-1">
            <div className="px-6 py-4 space-y-0">
              {/* Commission record summary */}
              {dispute?.commission_record && (
                <div className="border-b border-border/50 pb-4 mb-4">
                  <h3 className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wide mb-3">
                    Commission Record
                  </h3>
                  <div className="space-y-2">
                    <DetailRow label="Artist" value={dispute.commission_record.artist_name} />
                    <DetailRow label="Client" value={dispute.commission_record.client_name} />
                    <DetailRow label="Service" value={dispute.commission_record.service_name} />
                    <DetailRow
                      label="Date"
                      value={format(
                        parseISO(dispute.commission_record.booking_scheduled_at),
                        'MMM d, yyyy',
                      )}
                    />
                    <DetailRow
                      label="Total"
                      value={
                        <span className="tabular-nums font-semibold">
                          {formatCurrency(dispute.commission_record.total_cents)}
                        </span>
                      }
                    />
                    <DetailRow
                      label="Status"
                      value={
                        <CommissionStatusBadge
                          status={dispute.commission_record.status as 'pending' | 'approved' | 'paid' | 'cancelled' | 'disputed'}
                        />
                      }
                    />
                  </div>
                </div>
              )}

              {/* Dispute reason */}
              <div className="border-b border-border/50 pb-4 mb-4">
                <h3 className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wide mb-2">
                  Dispute Reason
                </h3>
                <div className="flex items-start gap-2">
                  <Avatar className="h-6 w-6 shrink-0 mt-0.5">
                    <AvatarImage src={dispute?.raised_by_avatar ?? undefined} />
                    <AvatarFallback className="text-[9px]">
                      {(dispute?.raised_by_name ?? '?').slice(0, 2).toUpperCase()}
                    </AvatarFallback>
                  </Avatar>
                  <div className="rounded-lg border border-border bg-muted/30 px-3 py-2.5 flex-1">
                    <p className="text-sm leading-relaxed">
                      &ldquo;{dispute?.reason}&rdquo;
                    </p>
                  </div>
                </div>
              </div>

              {/* Resolution section */}
              {canResolve && isOpen ? (
                <div className="space-y-4">
                  <h3 className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wide">
                    Resolution
                  </h3>

                  <RadioGroup
                    value={outcome}
                    onValueChange={(v) => setOutcome(v as DisputeOutcome)}
                    className="space-y-2"
                  >
                    <label className="flex items-start gap-3 p-3 rounded-lg border border-border cursor-pointer hover:border-primary/40 has-[:checked]:border-primary/60 has-[:checked]:bg-primary/[0.04]">
                      <RadioGroupItem value="upheld" className="mt-0.5 shrink-0" />
                      <div>
                        <p className="text-sm font-medium">Uphold dispute</p>
                        <p className="text-xs text-muted-foreground mt-0.5">
                          The commission record will be reset to pending for recalculation. The
                          artist will be notified.
                        </p>
                      </div>
                    </label>
                    <label className="flex items-start gap-3 p-3 rounded-lg border border-border cursor-pointer hover:border-primary/40 has-[:checked]:border-primary/60 has-[:checked]:bg-primary/[0.04]">
                      <RadioGroupItem value="dismissed" className="mt-0.5 shrink-0" />
                      <div>
                        <p className="text-sm font-medium">Dismiss dispute</p>
                        <p className="text-xs text-muted-foreground mt-0.5">
                          The original calculation stands and the commission is restored to approved.
                        </p>
                      </div>
                    </label>
                  </RadioGroup>

                  <div className="space-y-1.5">
                    <Label className="text-xs font-medium">
                      Resolution notes
                      {outcome === 'upheld' && (
                        <span className="text-destructive ml-1">*</span>
                      )}
                      {outcome === 'dismissed' && (
                        <span className="text-muted-foreground ml-1">(optional)</span>
                      )}
                    </Label>
                    <Textarea
                      value={resolutionNotes}
                      onChange={(e) => setResolutionNotes(e.target.value)}
                      placeholder="Explain your decision…"
                      className="resize-none h-20 text-sm"
                      maxLength={1000}
                    />
                  </div>
                </div>
              ) : isArtist && isOpen ? (
                /* Artist read-only — dispute open */
                <Alert className="border-amber-400/30 bg-amber-400/[0.06]">
                  <Clock className="h-4 w-4 text-amber-400" />
                  <AlertDescription className="text-xs text-amber-300 ml-2">
                    Your dispute is under review. You&apos;ll be notified when it&apos;s resolved.
                  </AlertDescription>
                </Alert>
              ) : !isOpen && dispute ? (
                /* Resolved/dismissed — read-only */
                <div className="space-y-3">
                  <h3 className="text-[10px] font-semibold text-muted-foreground uppercase tracking-wide">
                    Resolution
                  </h3>
                  <div
                    className={cn(
                      'rounded-lg border px-3 py-2.5 text-sm',
                      dispute.status === 'resolved'
                        ? 'border-[oklch(58%_0.18_145/0.3)] bg-[oklch(58%_0.18_145/0.06)]'
                        : 'border-border bg-muted/30',
                    )}
                  >
                    <p className="font-medium">
                      {dispute.status === 'resolved' ? 'Dispute upheld' : 'Dispute dismissed'}
                    </p>
                    {dispute.resolution_notes && (
                      <p className="text-xs text-muted-foreground mt-1">
                        {dispute.resolution_notes}
                      </p>
                    )}
                  </div>
                </div>
              ) : null}
            </div>
          </ScrollArea>
        )}

        {/* Footer — only shown when dispute is open and user can resolve */}
        {!resolved && canResolve && isOpen && (
          <div className="px-6 py-4 border-t border-border shrink-0 flex items-center justify-end gap-2">
            <Button variant="outline" onClick={handleClose}>
              Cancel
            </Button>
            <Button
              onClick={handleResolve}
              disabled={
                !outcome ||
                isPending ||
                (outcome === 'upheld' && resolutionNotes.trim().length === 0)
              }
            >
              {isPending && <Loader2 className="h-4 w-4 mr-1.5 animate-spin" />}
              Resolve dispute →
            </Button>
          </div>
        )}
        {!resolved && (!canResolve || !isOpen) && (
          <div className="px-6 py-4 border-t border-border shrink-0 flex justify-end">
            <Button variant="outline" onClick={handleClose}>
              Close
            </Button>
          </div>
        )}
      </SheetContent>
    </Sheet>
  )
}

'use client'

import { useState } from 'react'
import { useQuery } from '@tanstack/react-query'
import { Skeleton } from '@/components/ui/skeleton'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Button } from '@/components/ui/button'
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/components/ui/tooltip'
import { CheckCircle2 } from 'lucide-react'
import { format, parseISO } from 'date-fns'
import { formatCurrency, cn } from '@/lib/utils'
import { DisputeResolutionDrawer } from './DisputeResolutionDrawer'

type DisputeStatus = 'open' | 'resolved' | 'dismissed'

interface DisputeRow {
  id: string
  reason: string
  status: DisputeStatus
  resolution_notes: string | null
  created_at: string
  raised_by_name: string
  raised_by_avatar: string | null
  commission_record: {
    id: string
    status: string
    total_cents: number
    service_price_cents: number
    tip_cents: number
    booking_scheduled_at: string
    artist_name: string
    client_name: string
    service_name: string
  } | null
}

interface DisputesListProps {
  from: string
  to: string
  canResolve: boolean
  isArtist: boolean
}

export function DisputesList({ from, to, canResolve, isArtist }: DisputesListProps) {
  const [statusFilter, setStatusFilter] = useState<'all' | DisputeStatus>('open')
  const [selectedDispute, setSelectedDispute] = useState<DisputeRow | null>(null)
  const [drawerOpen, setDrawerOpen] = useState(false)

  const { data, isLoading } = useQuery<{ data: DisputeRow[] }>({
    queryKey: ['commission-disputes', from, to, statusFilter],
    queryFn: () => {
      const params = new URLSearchParams({ from, to })
      if (statusFilter !== 'all') params.set('status', statusFilter)
      return fetch(`/api/commissions/disputes?${params}`).then((r) => r.json())
    },
    staleTime: 15_000,
  })

  const disputes = data?.data ?? []

  function openDrawer(dispute: DisputeRow) {
    setSelectedDispute(dispute)
    setDrawerOpen(true)
  }

  if (isLoading) {
    return (
      <div className="px-6 py-4 space-y-2">
        <div className="flex gap-2 pb-3 border-b border-border">
          <Skeleton className="h-8 w-[120px] rounded-md" />
        </div>
        {Array.from({ length: 4 }).map((_, i) => (
          <div
            key={i}
            className="flex items-center gap-4 py-3 border-b border-border/50"
            style={{ animationDelay: `${i * 40}ms`, animationFillMode: 'both' }}
          >
            <Skeleton className="h-4 w-[80px]" />
            <Skeleton className="h-4 w-[140px]" />
            <Skeleton className="h-4 w-[100px]" />
            <Skeleton className="h-4 w-[60px] ml-auto" />
            <Skeleton className="h-5 w-[70px] rounded-full" />
          </div>
        ))}
      </div>
    )
  }

  return (
    <>
      {/* Filter bar */}
      <div className="px-6 py-3 border-b border-border flex items-center gap-2">
        <Select
          value={statusFilter}
          onValueChange={(v) => setStatusFilter(v as 'all' | DisputeStatus)}
        >
          <SelectTrigger className="h-8 w-[130px] text-xs">
            <SelectValue />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="open">Open</SelectItem>
            <SelectItem value="resolved">Resolved</SelectItem>
            <SelectItem value="dismissed">Dismissed</SelectItem>
            <SelectItem value="all">All</SelectItem>
          </SelectContent>
        </Select>
        <span className="text-xs text-muted-foreground ml-auto tabular-nums">
          {disputes.length} dispute{disputes.length !== 1 ? 's' : ''}
        </span>
      </div>

      {disputes.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 px-6 text-center">
          <CheckCircle2 className="h-10 w-10 text-muted-foreground/40 mb-4" />
          <p className="text-sm font-medium text-foreground mb-1">
            {statusFilter === 'open' ? 'No open disputes' : 'No disputes have been raised.'}
          </p>
          {statusFilter === 'open' && (
            <p className="text-xs text-muted-foreground max-w-xs">
              Artists can raise disputes on their commission records if they believe a calculation is
              incorrect.
            </p>
          )}
        </div>
      ) : (
        <Table>
          <TableHeader>
            <TableRow className="hover:bg-transparent">
              <TableHead className="text-xs">Raised</TableHead>
              {!isArtist && <TableHead className="text-xs">Artist / Client</TableHead>}
              <TableHead className="text-xs">Service</TableHead>
              <TableHead className="text-right text-xs">Amount</TableHead>
              <TableHead className="text-xs">Reason</TableHead>
              <TableHead className="text-xs">Status</TableHead>
              <TableHead className="w-20 text-xs">Action</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {disputes.map((d) => (
              <TableRow
                key={d.id}
                className="hover:bg-muted/30 transition-colors cursor-pointer"
                onClick={() => openDrawer(d)}
              >
                <TableCell>
                  <p className="text-sm tabular-nums">
                    {format(parseISO(d.created_at), 'MMM d, yy')}
                  </p>
                  <p className="text-xs text-muted-foreground">by {d.raised_by_name}</p>
                </TableCell>
                {!isArtist && (
                  <TableCell className="text-sm">
                    {d.commission_record
                      ? `${d.commission_record.artist_name} / ${d.commission_record.client_name}`
                      : '—'}
                  </TableCell>
                )}
                <TableCell className="text-sm">
                  {d.commission_record?.service_name ?? '—'}
                </TableCell>
                <TableCell className="text-right tabular-nums text-sm">
                  {d.commission_record ? formatCurrency(d.commission_record.total_cents) : '—'}
                </TableCell>
                <TableCell className="max-w-[160px]">
                  <Tooltip>
                    <TooltipTrigger asChild>
                      <span className="text-sm truncate block cursor-default">
                        {d.reason.length > 40 ? `${d.reason.slice(0, 40)}…` : d.reason}
                      </span>
                    </TooltipTrigger>
                    {d.reason.length > 40 && (
                      <TooltipContent className="max-w-[240px] text-xs">{d.reason}</TooltipContent>
                    )}
                  </Tooltip>
                </TableCell>
                <TableCell>
                  <span
                    className={cn(
                      `badge-dispute-${d.status}`,
                      'inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium',
                    )}
                  >
                    {d.status.charAt(0).toUpperCase() + d.status.slice(1)}
                  </span>
                </TableCell>
                <TableCell>
                  <Button
                    variant="ghost"
                    size="sm"
                    className="h-7 text-xs"
                    onClick={(e) => {
                      e.stopPropagation()
                      openDrawer(d)
                    }}
                  >
                    {canResolve && d.status === 'open' ? 'Resolve' : 'View'}
                  </Button>
                </TableCell>
              </TableRow>
            ))}
          </TableBody>
        </Table>
      )}

      <DisputeResolutionDrawer
        open={drawerOpen}
        onOpenChange={(o) => {
          setDrawerOpen(o)
          if (!o) setSelectedDispute(null)
        }}
        dispute={selectedDispute}
        canResolve={canResolve}
        isArtist={isArtist}
      />
    </>
  )
}

'use client'

import { useState } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { Alert, AlertDescription } from '@/components/ui/alert'
import { Loader2, Check, Clock } from 'lucide-react'
import { formatCurrency, cn } from '@/lib/utils'
import { toast } from 'sonner'
import { CommissionPreview } from './CommissionPreview'
import { CommissionStatusBadge } from './CommissionStatusBadge'
import type { CommissionRecord, CommissionRuleSnapshot } from '@/lib/supabase/types'

const MATCHED_BY_LABELS: Record<CommissionRuleSnapshot['matched_by'], string> = {
  service_specific: 'Service rule',
  catch_all: 'All services',
  artist_default: 'Artist default',
  none: 'No rule',
}

interface AppointmentCommissionSectionProps {
  bookingId: string
  bookingStatus: string
  tipCents: number
  canApprove: boolean
}

export function AppointmentCommissionSection({
  bookingId,
  bookingStatus,
  tipCents,
  canApprove,
}: AppointmentCommissionSectionProps) {
  const [isApproving, setIsApproving] = useState(false)
  const queryClient = useQueryClient()

  const { data, isLoading } = useQuery<{ data: CommissionRecord | null }>({
    queryKey: ['booking-commission', bookingId],
    queryFn: () =>
      fetch(`/api/bookings/${bookingId}/commission`).then((r) => r.json()),
    staleTime: 30_000,
    enabled: bookingStatus === 'completed',
  })

  const record = data?.data
  const snapshot = record?.rule_snapshot as CommissionRuleSnapshot | undefined

  async function handleInlineApprove() {
    if (!record || isApproving) return
    setIsApproving(true)
    try {
      const resp = await fetch('/api/commissions/records/approve', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ record_ids: [record.id] }),
      })
      const json = await resp.json()
      if (!resp.ok) throw new Error(json.error ?? 'Failed to approve')
      toast.success('Commission approved')
      await queryClient.invalidateQueries({ queryKey: ['booking-commission', bookingId] })
      await queryClient.invalidateQueries({ queryKey: ['commission-records'] })
    } catch (err) {
      toast.error(err instanceof Error ? err.message : 'Failed to approve commission')
    } finally {
      setIsApproving(false)
    }
  }

  if (bookingStatus !== 'completed') return null

  if (isLoading) {
    return (
      <Card className="shadow-soft">
        <CardHeader className="pb-3">
          <Skeleton className="h-4 w-[100px]" />
        </CardHeader>
        <CardContent className="space-y-3">
          {Array.from({ length: 3 }).map((_, i) => (
            <div key={i} className="flex items-center justify-between">
              <Skeleton className="h-4 w-[100px]" />
              <Skeleton className="h-4 w-[60px]" />
            </div>
          ))}
        </CardContent>
      </Card>
    )
  }

  if (!record || !snapshot) return null

  const isPending = record.status === 'pending'

  return (
    <>
      {/* Pending reminder alert */}
      {isPending && (
        <Alert className="border-amber-400/30 bg-amber-400/[0.06] mb-4">
          <Clock className="h-4 w-4 text-amber-400" />
          <AlertDescription className="text-xs text-amber-300 ml-2">
            Commission pending approval — {formatCurrency(record.total_cents)}.{' '}
            {canApprove && (
              <button
                className="underline hover:no-underline"
                onClick={handleInlineApprove}
                disabled={isApproving}
              >
                Approve now
              </button>
            )}
          </AlertDescription>
        </Alert>
      )}

      <Card className="shadow-soft">
        <CardHeader className="pb-3">
          <div className="flex items-center justify-between">
            <CardTitle className="text-sm font-medium">Commission</CardTitle>
            <CommissionStatusBadge status={record.status} />
          </div>
        </CardHeader>
        <CardContent className="space-y-3">
          {/* Rule match type */}
          <div className="flex items-center justify-between text-sm">
            <span className="text-muted-foreground text-xs">Rule</span>
            <span
              className={cn(
                `pill-rule-${snapshot.matched_by}`,
                'inline-flex h-5 rounded-full px-2 text-[10px] font-medium items-center',
              )}
            >
              {MATCHED_BY_LABELS[snapshot.matched_by]}
            </span>
          </div>

          {/* Calculation preview */}
          <CommissionPreview
            price={record.service_price_cents}
            tip={tipCents}
            rule={{
              percentage: snapshot.percentage,
              flat_fee_cents: snapshot.flat_fee_cents,
              tip_split_pct: snapshot.tip_split_pct ?? 100,
            }}
            showExampleLabel={false}
            className="mt-2"
          />

          {/* Approve inline button */}
          {canApprove && isPending && (
            <div className="pt-2">
              <Button
                size="sm"
                className="w-full"
                onClick={handleInlineApprove}
                disabled={isApproving}
              >
                {isApproving ? (
                  <Loader2 className="h-3.5 w-3.5 mr-1.5 animate-spin" />
                ) : (
                  <Check className="h-3.5 w-3.5 mr-1.5" />
                )}
                Approve commission
              </Button>
            </div>
          )}
        </CardContent>
      </Card>
    </>
  )
}

'use client'

import { useState, useMemo } from 'react'
import { useQuery, useQueryClient } from '@tanstack/react-query'
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from '@/components/ui/table'
import { Checkbox } from '@/components/ui/checkbox'
import { Button } from '@/components/ui/button'
import { Skeleton } from '@/components/ui/skeleton'
import { Input } from '@/components/ui/input'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from '@/components/ui/dropdown-menu'
import {
  Tooltip,
  TooltipContent,
  TooltipTrigger,
} from '@/components/ui/tooltip'
import { ReceiptText, MoreHorizontal } from 'lucide-react'
import { format, parseISO } from 'date-fns'
import { formatCurrency, cn } from '@/lib/utils'
import { BulkApprovalFooter } from './BulkApprovalFooter'
import { RecordDetailDrawer } from './RecordDetailDrawer'
import { RaiseDisputeModal } from './RaiseDisputeModal'
import type { CommissionRuleSnapshot } from '@/lib/supabase/types'

const MATCHED_BY_LABELS: Record<CommissionRuleSnapshot['matched_by'], string> = {
  service_specific: 'Service rule',
  catch_all: 'All services',
  artist_default: 'Artist default',
  none: 'No rule',
}

interface RecordRow {
  id: string
  booking_id: string
  artist_id: string
  service_price_cents: number
  tip_cents: number
  commission_cents: number
  tip_commission_cents: number
  total_cents: number
  status: 'pending' | 'approved' | 'paid' | 'cancelled' | 'disputed'
  rule_snapshot: CommissionRuleSnapshot
  created_at: string
  artists: { display_name: string; avatar_url: string | null } | null
  services: { name: string } | null
  bookings: {
    scheduled_at: string
    clients: { first_name: string; last_name: string | null } | null
  } | null
}

interface RecordsTableProps {
  from: string
  to: string
  isArtist: boolean
  canApprove: boolean
  canManage: boolean
  isOwner: boolean
}

export function RecordsTable({
  from,
  to,
  isArtist,
  canApprove,
  canManage,
  isOwner,
}: RecordsTableProps) {
  const [artistFilter, setArtistFilter] = useState('all')
  const [statusFilter, setStatusFilter] = useState('all')
  const [searchQuery, setSearchQuery] = useState('')
  const [selectedIds, setSelectedIds] = useState<string[]>([])
  const [detailId, setDetailId] = useState<string | null>(null)
  const [detailOpen, setDetailOpen] = useState(false)
  const [disputeRecord, setDisputeRecord] = useState<{
    id: string
    total_cents: number
    service_name: string
    booking_scheduled_at: string
  } | null>(null)
  const [disputeOpen, setDisputeOpen] = useState(false)
  const queryClient = useQueryClient()

  const params = new URLSearchParams({ from, to })
  if (statusFilter !== 'all') params.set('status', statusFilter)
  if (artistFilter !== 'all') params.set('artist_id', artistFilter)
  if (searchQuery.trim()) params.set('q', searchQuery.trim())

  const { data, isLoading } = useQuery<{ data: RecordRow[]; total_count: number }>({
    queryKey: ['commission-records', from, to, artistFilter, statusFilter, searchQuery],
    queryFn: () => fetch(`/api/commissions/records?${params}`).then((r) => r.json()),
    staleTime: 30_000,
  })

  // Artists list for filter dropdown
  const { data: artistsData } = useQuery<{ data: Array<{ id: string; display_name: string }> }>({
    queryKey: ['artists-list'],
    queryFn: () => fetch('/api/artists').then((r) => r.json()),
    staleTime: 300_000,
    enabled: !isArtist,
  })

  const records = data?.data ?? []
  const artists = artistsData?.data ?? []

  // Totals for footer row
  const totals = useMemo(() => {
    const all = records
    return {
      price: all.reduce((s, r) => s + r.service_price_cents, 0),
      tipComm: all.reduce((s, r) => s + r.tip_commission_cents, 0),
      comm: all.reduce((s, r) => s + r.commission_cents, 0),
      total: all.reduce((s, r) => s + r.total_cents, 0),
    }
  }, [records])

  // Selection logic
  const pendingIds = records.filter((r) => r.status === 'pending').map((r) => r.id)
  const allPendingSelected =
    pendingIds.length > 0 && pendingIds.every((id) => selectedIds.includes(id))
  const selectedTotalCents = records
    .filter((r) => selectedIds.includes(r.id))
    .reduce((s, r) => s + r.total_cents, 0)

  function toggleAll() {
    if (allPendingSelected) {
      setSelectedIds([])
    } else {
      setSelectedIds(pendingIds)
    }
  }

  function toggleRow(id: string) {
    setSelectedIds((prev) =>
      prev.includes(id) ? prev.filter((x) => x !== id) : [...prev, id],
    )
  }

  const hasActiveFilters =
    artistFilter !== 'all' || statusFilter !== 'all' || searchQuery.trim().length > 0

  if (isLoading) {
    return (
      <div className="space-y-2 px-6 pt-4">
        <div className="flex gap-2 pb-3 border-b border-border">
          {!isArtist && <Skeleton className="h-8 w-[140px] rounded-md" />}
          <Skeleton className="h-8 w-[120px] rounded-md" />
          <Skeleton className="h-8 w-[100px] rounded-md" />
          <Skeleton className="h-8 w-[200px] ml-auto rounded-md" />
        </div>
        {Array.from({ length: 8 }).map((_, i) => (
          <div
            key={i}
            className="flex items-center gap-4 py-3 border-b border-border/50"
            style={{ animationDelay: `${i * 40}ms`, animationFillMode: 'both' }}
          >
            <Skeleton className="h-4 w-4 rounded" />
            <Skeleton className="h-4 w-[80px]" />
            <Skeleton className="h-4 w-[100px]" />
            <Skeleton className="h-4 w-[120px]" />
            <Skeleton className="h-4 w-[60px] ml-auto" />
            <Skeleton className="h-5 w-[80px] rounded-full" />
          </div>
        ))}
      </div>
    )
  }

  if (records.length === 0 && !hasActiveFilters) {
    return (
      <div className="flex flex-col items-center justify-center py-16 px-6 text-center">
        <ReceiptText className="h-10 w-10 text-muted-foreground/40 mb-4" />
        <p className="text-sm font-medium text-foreground mb-1">
          {isArtist ? 'No commissions yet' : 'No commissions recorded'}
        </p>
        <p className="text-xs text-muted-foreground max-w-xs">
          {isArtist
            ? 'Your commissions will appear here once you complete a booking.'
            : 'Complete a booking to start tracking commissions. Records are created automatically when a booking is marked complete.'}
        </p>
      </div>
    )
  }

  return (
    <>
      {/* Filter bar */}
      <div className="flex flex-wrap items-center gap-2 px-6 py-3 border-b border-border">
        {!isArtist && (
          <Select value={artistFilter} onValueChange={setArtistFilter}>
            <SelectTrigger className="h-8 w-[140px] text-xs">
              <SelectValue placeholder="All artists" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="all">All artists</SelectItem>
              {artists.map((a) => (
                <SelectItem key={a.id} value={a.id}>
                  {a.display_name}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        )}

        <Select value={statusFilter} onValueChange={setStatusFilter}>
          <SelectTrigger className="h-8 w-[120px] text-xs">
            <SelectValue placeholder="All statuses" />
          </SelectTrigger>
          <SelectContent>
            <SelectItem value="all">All statuses</SelectItem>
            <SelectItem value="pending">Pending</SelectItem>
            <SelectItem value="approved">Approved</SelectItem>
            <SelectItem value="paid">Paid</SelectItem>
            <SelectItem value="cancelled">Cancelled</SelectItem>
            <SelectItem value="disputed">Disputed</SelectItem>
          </SelectContent>
        </Select>

        <div className="ml-auto flex items-center gap-2">
          <Input
            placeholder="Search client or service…"
            className="h-8 w-[200px] text-xs"
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
          />
          {hasActiveFilters && (
            <Button
              variant="ghost"
              size="sm"
              className="h-8 text-xs text-muted-foreground"
              onClick={() => {
                setArtistFilter('all')
                setStatusFilter('all')
                setSearchQuery('')
              }}
            >
              Clear
            </Button>
          )}
        </div>
      </div>

      {records.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-16 px-6 text-center">
          <ReceiptText className="h-10 w-10 text-muted-foreground/40 mb-4" />
          <p className="text-sm font-medium text-foreground mb-1">No results</p>
          <p className="text-xs text-muted-foreground max-w-xs">
            Try adjusting your filters to find what you&apos;re looking for.
          </p>
        </div>
      ) : (
        <div className="overflow-x-auto">
          <Table>
            <TableHeader>
              <TableRow className="hover:bg-transparent">
                {(canApprove || isOwner) && (
                  <TableHead className="w-10 pl-4">
                    <Checkbox
                      checked={allPendingSelected}
                      onCheckedChange={toggleAll}
                      aria-label="Select all pending"
                    />
                  </TableHead>
                )}
                <TableHead className="text-xs w-[100px]">Date</TableHead>
                {!isArtist && <TableHead className="text-xs w-[140px]">Artist</TableHead>}
                <TableHead className="text-xs w-[120px]">Client</TableHead>
                <TableHead className="text-xs w-[120px]">Service</TableHead>
                <TableHead className="text-right text-xs w-[80px]">Price</TableHead>
                <TableHead className="text-xs w-[110px] hidden lg:table-cell">Rule</TableHead>
                <TableHead className="text-right text-xs w-[80px] hidden lg:table-cell">
                  Tip
                </TableHead>
                <TableHead className="text-right text-xs w-[90px]">Commission</TableHead>
                <TableHead className="text-right text-xs w-[80px] font-semibold">Total</TableHead>
                <TableHead className="text-xs w-[100px]">Status</TableHead>
                <TableHead className="w-10" />
              </TableRow>
            </TableHeader>
            <TableBody>
              {records.map((record) => {
                const clientName = record.bookings?.clients
                  ? `${record.bookings.clients.first_name} ${record.bookings.clients.last_name ?? ''}`.trim()
                  : '—'
                const matchedBy = record.rule_snapshot?.matched_by ?? 'none'
                const isSelected = selectedIds.includes(record.id)
                const canSelect = record.status === 'pending' && (canApprove || isOwner)

                return (
                  <TableRow
                    key={record.id}
                    className={cn(
                      'hover:bg-muted/30 transition-colors cursor-pointer',
                      isSelected && 'bg-primary/[0.04]',
                    )}
                    onClick={() => {
                      setDetailId(record.id)
                      setDetailOpen(true)
                    }}
                  >
                    {(canApprove || isOwner) && (
                      <TableCell className="pl-4" onClick={(e) => e.stopPropagation()}>
                        {canSelect && (
                          <Checkbox
                            checked={isSelected}
                            onCheckedChange={() => toggleRow(record.id)}
                            aria-label={`Select record ${record.id}`}
                          />
                        )}
                      </TableCell>
                    )}
                    <TableCell className="text-sm tabular-nums">
                      {record.bookings?.scheduled_at
                        ? format(parseISO(record.bookings.scheduled_at), 'MMM d, yy')
                        : '—'}
                    </TableCell>
                    {!isArtist && (
                      <TableCell>
                        <span className="text-sm truncate block max-w-[120px]">
                          {record.artists?.display_name ?? '—'}
                        </span>
                      </TableCell>
                    )}
                    <TableCell>
                      <span className="text-sm truncate block max-w-[100px]" title={clientName}>
                        {clientName.length > 20 ? `${clientName.slice(0, 20)}…` : clientName}
                      </span>
                    </TableCell>
                    <TableCell>
                      <span
                        className="text-sm truncate block max-w-[100px]"
                        title={record.services?.name}
                      >
                        {(record.services?.name ?? '—').length > 22
                          ? `${record.services!.name.slice(0, 22)}…`
                          : (record.services?.name ?? '—')}
                      </span>
                    </TableCell>
                    <TableCell className="text-right tabular-nums text-sm">
                      {formatCurrency(record.service_price_cents)}
                    </TableCell>
                    <TableCell className="hidden lg:table-cell">
                      <span
                        className={cn(
                          `pill-rule-${matchedBy}`,
                          'inline-flex h-5 rounded-full px-2 text-[10px] font-medium items-center',
                        )}
                      >
                        {MATCHED_BY_LABELS[matchedBy]}
                      </span>
                    </TableCell>
                    <TableCell className="text-right tabular-nums text-sm text-muted-foreground hidden lg:table-cell">
                      {formatCurrency(record.tip_commission_cents)}
                    </TableCell>
                    <TableCell className="text-right tabular-nums text-sm">
                      {formatCurrency(record.commission_cents)}
                    </TableCell>
                    <TableCell className="text-right tabular-nums text-sm font-semibold">
                      {formatCurrency(record.total_cents)}
                    </TableCell>
                    <TableCell>
                      <span
                        className={cn(
                          `badge-commission-${record.status}`,
                          'inline-flex h-5 items-center rounded-full px-2 text-[10px] font-medium',
                        )}
                      >
                        {record.status.charAt(0).toUpperCase() + record.status.slice(1)}
                      </span>
                    </TableCell>
                    <TableCell onClick={(e) => e.stopPropagation()}>
                      <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                          <Button variant="ghost" size="icon" className="h-7 w-7">
                            <MoreHorizontal className="h-3.5 w-3.5" />
                          </Button>
                        </DropdownMenuTrigger>
                        <DropdownMenuContent align="end" className="text-sm">
                          {canApprove && record.status === 'pending' && (
                            <>
                              <DropdownMenuItem
                                onClick={async () => {
                                  const resp = await fetch('/api/commissions/records/approve', {
                                    method: 'POST',
                                    headers: { 'Content-Type': 'application/json' },
                                    body: JSON.stringify({ record_ids: [record.id] }),
                                  })
                                  if (resp.ok) {
                                    const { toast } = await import('sonner')
                                    toast.success('Commission approved')
                                    queryClient.invalidateQueries({ queryKey: ['commission-records'] })
                                  }
                                }}
                              >
                                Approve
                              </DropdownMenuItem>
                              <DropdownMenuSeparator />
                            </>
                          )}
                          {canManage && record.status === 'pending' && !isArtist && (
                            <DropdownMenuItem
                              onClick={async () => {
                                const resp = await fetch(
                                  `/api/commissions/records/${record.id}/recalculate`,
                                  { method: 'POST' },
                                )
                                if (resp.ok) {
                                  const { toast } = await import('sonner')
                                  toast.success('Commission recalculated')
                                  queryClient.invalidateQueries({ queryKey: ['commission-records'] })
                                }
                              }}
                            >
                              Recalculate
                            </DropdownMenuItem>
                          )}
                          {record.status !== 'cancelled' && record.status !== 'disputed' && (
                            <DropdownMenuItem
                              onClick={() => {
                                setDisputeRecord({
                                  id: record.id,
                                  total_cents: record.total_cents,
                                  service_name: record.services?.name ?? '—',
                                  booking_scheduled_at:
                                    record.bookings?.scheduled_at ?? record.created_at,
                                })
                                setDisputeOpen(true)
                              }}
                            >
                              Raise dispute
                            </DropdownMenuItem>
                          )}
                          {isOwner &&
                            ['pending', 'approved'].includes(record.status) && (
                              <>
                                <DropdownMenuSeparator />
                                <DropdownMenuItem
                                  className="text-destructive"
                                  onClick={() => {
                                    setDetailId(record.id)
                                    setDetailOpen(true)
                                  }}
                                >
                                  Cancel
                                </DropdownMenuItem>
                              </>
                            )}
                        </DropdownMenuContent>
                      </DropdownMenu>
                    </TableCell>
                  </TableRow>
                )
              })}

              {/* Column totals footer */}
              <TableRow className="border-t-2 border-border font-semibold bg-muted/30 hover:bg-muted/30">
                <TableCell
                  colSpan={(canApprove || isOwner ? 1 : 0) + (isArtist ? 0 : 1) + 4}
                  className="text-xs text-muted-foreground py-2 px-4"
                >
                  {records.length} records
                </TableCell>
                <TableCell className="tabular-nums text-xs py-2 text-right">
                  {formatCurrency(totals.price)}
                </TableCell>
                <TableCell className="hidden lg:table-cell" />
                <TableCell className="tabular-nums text-xs py-2 text-right hidden lg:table-cell">
                  {formatCurrency(totals.tipComm)}
                </TableCell>
                <TableCell className="tabular-nums text-xs py-2 text-right">
                  {formatCurrency(totals.comm)}
                </TableCell>
                <TableCell className="tabular-nums text-sm font-bold py-2 text-right">
                  {formatCurrency(totals.total)}
                </TableCell>
                <TableCell colSpan={2} />
              </TableRow>
            </TableBody>
          </Table>
        </div>
      )}

      {/* Bulk action footer */}
      <BulkApprovalFooter
        selectedIds={selectedIds}
        selectedTotalCents={selectedTotalCents}
        onClear={() => setSelectedIds([])}
        canApprove={canApprove}
      />

      {/* Record detail drawer */}
      <RecordDetailDrawer
        recordId={detailId}
        open={detailOpen}
        onOpenChange={(o) => {
          setDetailOpen(o)
          if (!o) setDetailId(null)
        }}
        currentMemberRole={isArtist ? 'artist' : isOwner ? 'owner' : 'admin'}
        canApprove={canApprove}
        canManage={canManage}
      />

      {/* Raise dispute modal */}
      <RaiseDisputeModal
        open={disputeOpen}
        onOpenChange={(o) => {
          setDisputeOpen(o)
          if (!o) setDisputeRecord(null)
        }}
        record={disputeRecord}
      />
    </>
  )
}

