'use client'

import { useCallback, useMemo } from 'react'
import { useRouter, useSearchParams, usePathname } from 'next/navigation'
import { useQuery } from '@tanstack/react-query'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Button } from '@/components/ui/button'
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select'
import { Download, Plus, ChevronLeft, ChevronRight } from 'lucide-react'
import {
  startOfMonth,
  endOfMonth,
  subMonths,
  addMonths,
  format,
  startOfYear,
  endOfYear,
  startOfQuarter,
  endOfQuarter,
} from 'date-fns'
import { CommissionsDashboard } from './CommissionsDashboard'
import { RecordsTable } from './RecordsTable'
import { RulesList } from './RulesList'
import { AdjustmentsList } from './AdjustmentsList'
import { DisputesList } from './DisputesList'
import { AdjustmentModal } from './AdjustmentModal'
import { RuleEditorDrawer } from './RuleEditorDrawer'
import { useState } from 'react'

// ---------------------------------------------------------------------------
// Period utilities
// ---------------------------------------------------------------------------

type PeriodPreset =
  | 'this_month'
  | 'last_month'
  | 'this_quarter'
  | 'last_quarter'
  | 'this_year'
  | 'last_year'

function computeDateRange(period: PeriodPreset): { from: string; to: string; label: string } {
  const now = new Date()
  switch (period) {
    case 'this_month':
      return {
        from: format(startOfMonth(now), 'yyyy-MM-dd'),
        to: format(endOfMonth(now), 'yyyy-MM-dd'),
        label: format(now, 'MMMM yyyy'),
      }
    case 'last_month': {
      const last = subMonths(now, 1)
      return {
        from: format(startOfMonth(last), 'yyyy-MM-dd'),
        to: format(endOfMonth(last), 'yyyy-MM-dd'),
        label: format(last, 'MMMM yyyy'),
      }
    }
    case 'this_quarter':
      return {
        from: format(startOfQuarter(now), 'yyyy-MM-dd'),
        to: format(endOfQuarter(now), 'yyyy-MM-dd'),
        label: `Q${Math.ceil((now.getMonth() + 1) / 3)} ${now.getFullYear()}`,
      }
    case 'last_quarter': {
      const lastQ = subMonths(now, 3)
      return {
        from: format(startOfQuarter(lastQ), 'yyyy-MM-dd'),
        to: format(endOfQuarter(lastQ), 'yyyy-MM-dd'),
        label: `Q${Math.ceil((lastQ.getMonth() + 1) / 3)} ${lastQ.getFullYear()}`,
      }
    }
    case 'this_year':
      return {
        from: format(startOfYear(now), 'yyyy-MM-dd'),
        to: format(endOfYear(now), 'yyyy-MM-dd'),
        label: `${now.getFullYear()}`,
      }
    case 'last_year': {
      const lastY = subMonths(now, 12)
      return {
        from: format(startOfYear(lastY), 'yyyy-MM-dd'),
        to: format(endOfYear(lastY), 'yyyy-MM-dd'),
        label: `${lastY.getFullYear()}`,
      }
    }
  }
}

const PERIOD_OPTIONS: { value: PeriodPreset; label: string }[] = [
  { value: 'this_month', label: 'This month' },
  { value: 'last_month', label: 'Last month' },
  { value: 'this_quarter', label: 'This quarter' },
  { value: 'last_quarter', label: 'Last quarter' },
  { value: 'this_year', label: 'This year' },
  { value: 'last_year', label: 'Last year' },
]

// ---------------------------------------------------------------------------
// PeriodSelector
// ---------------------------------------------------------------------------

interface PeriodSelectorProps {
  period: PeriodPreset
  onChange: (period: PeriodPreset) => void
  label: string
}

function PeriodSelector({ period, onChange, label }: PeriodSelectorProps) {
  const periodIndex = PERIOD_OPTIONS.findIndex((o) => o.value === period)

  function prevPeriod() {
    const now = new Date()
    if (period === 'this_month') {
      onChange('last_month')
    } else if (period === 'last_month') {
      // Go back one more month — we only have two discrete options, so wrap to this_month
      onChange('this_month')
    } else if (period === 'this_quarter') {
      onChange('last_quarter')
    } else if (period === 'this_quarter') {
      onChange('last_quarter')
    } else if (period === 'this_year') {
      onChange('last_year')
    } else {
      // Already at boundaries — no-op
    }
  }

  function nextPeriod() {
    if (period === 'last_month') {
      onChange('this_month')
    } else if (period === 'last_quarter') {
      onChange('this_quarter')
    } else if (period === 'last_year') {
      onChange('this_year')
    }
  }

  const canGoNext = period === 'last_month' || period === 'last_quarter' || period === 'last_year'

  return (
    <div className="flex items-center gap-1">
      <Button
        variant="ghost"
        size="icon"
        className="h-7 w-7 text-muted-foreground"
        onClick={prevPeriod}
        aria-label="Previous period"
      >
        <ChevronLeft className="h-3.5 w-3.5" />
      </Button>

      <Select value={period} onValueChange={(v) => onChange(v as PeriodPreset)}>
        <SelectTrigger className="h-7 min-w-[130px] text-xs border-none shadow-none px-2 font-medium">
          <SelectValue>{label}</SelectValue>
        </SelectTrigger>
        <SelectContent align="end">
          {PERIOD_OPTIONS.map((opt) => (
            <SelectItem key={opt.value} value={opt.value} className="text-xs">
              {opt.label}
            </SelectItem>
          ))}
        </SelectContent>
      </Select>

      <Button
        variant="ghost"
        size="icon"
        className="h-7 w-7 text-muted-foreground"
        onClick={nextPeriod}
        disabled={!canGoNext}
        aria-label="Next period"
      >
        <ChevronRight className="h-3.5 w-3.5" />
      </Button>
    </div>
  )
}

// ---------------------------------------------------------------------------
// CommissionsHub
// ---------------------------------------------------------------------------

interface CommissionsHubProps {
  isArtist: boolean
  canApprove: boolean
  canManage: boolean
  isOwner: boolean
  /** Pre-filter to a specific artist (from URL param, e.g. artist page link) */
  defaultArtistId?: string
}

export function CommissionsHub({
  isArtist,
  canApprove,
  canManage,
  isOwner,
  defaultArtistId,
}: CommissionsHubProps) {
  const router = useRouter()
  const pathname = usePathname()
  const searchParams = useSearchParams()

  // ── URL-driven state ──────────────────────────────────────────────────────
  const tab = (searchParams.get('tab') ?? 'dashboard') as
    | 'dashboard'
    | 'records'
    | 'rules'
    | 'adjustments'
    | 'disputes'

  const period = (searchParams.get('period') ?? 'this_month') as PeriodPreset

  const updateParam = useCallback(
    (key: string, value: string) => {
      const params = new URLSearchParams(searchParams.toString())
      params.set(key, value)
      router.replace(`${pathname}?${params.toString()}`, { scroll: false })
    },
    [router, pathname, searchParams],
  )

  const { from, to, label } = useMemo(() => computeDateRange(period), [period])

  // ── Local modal state ─────────────────────────────────────────────────────
  const [adjustmentOpen, setAdjustmentOpen] = useState(false)
  const [ruleDrawerOpen, setRuleDrawerOpen] = useState(false)

  // ── Open dispute count badge ──────────────────────────────────────────────
  const { data: disputeCountData } = useQuery<{ data: { open_count: number } }>({
    queryKey: ['commission-disputes-count'],
    queryFn: () => fetch('/api/commissions/disputes/count').then((r) => r.json()),
    staleTime: 30_000,
    enabled: !isArtist,
  })
  const openDisputeCount = disputeCountData?.data?.open_count ?? 0

  // ── Export handler ────────────────────────────────────────────────────────
  function handleExport() {
    const params = new URLSearchParams({ from, to, format: 'csv' })
    window.open(`/api/commissions/export?${params}`, '_blank')
  }

  // ── Add button per tab ────────────────────────────────────────────────────
  function renderAddButton() {
    if (isArtist) return null
    if (tab === 'adjustments' && canManage) {
      return (
        <Button size="sm" className="h-8 text-xs gap-1.5" onClick={() => setAdjustmentOpen(true)}>
          <Plus className="h-3.5 w-3.5" />
          Add adjustment
        </Button>
      )
    }
    if (tab === 'rules' && canManage) {
      return (
        <Button size="sm" className="h-8 text-xs gap-1.5" onClick={() => setRuleDrawerOpen(true)}>
          <Plus className="h-3.5 w-3.5" />
          Add rule
        </Button>
      )
    }
    return null
  }

  return (
    <div className="flex flex-col flex-1 overflow-hidden h-full">
      {/* ── Page header ───────────────────────────────────────────────────── */}
      <div className="flex items-center justify-between px-6 py-4 border-b border-border/40 shrink-0">
        <div>
          <h1 className="text-lg font-semibold">Commissions</h1>
          <p className="text-xs text-muted-foreground mt-0.5">
            {isArtist ? 'Your earnings and commission records' : 'Studio-wide commission management'}
          </p>
        </div>

        <div className="flex items-center gap-2">
          <PeriodSelector
            period={period}
            onChange={(p) => updateParam('period', p)}
            label={label}
          />

          {tab !== 'rules' && (
            <Button
              variant="outline"
              size="sm"
              className="h-8 text-xs gap-1.5"
              onClick={handleExport}
            >
              <Download className="h-3.5 w-3.5" />
              Export
            </Button>
          )}

          {renderAddButton()}
        </div>
      </div>

      {/* ── Tabs ──────────────────────────────────────────────────────────── */}
      <Tabs
        value={tab}
        onValueChange={(v) => updateParam('tab', v)}
        className="flex flex-col flex-1 overflow-hidden"
      >
        <TabsList className="shrink-0 w-full justify-start gap-0 rounded-none border-b border-border bg-transparent px-6 h-10">
          <TabsTrigger
            value="dashboard"
            className="rounded-none border-b-2 border-transparent data-[state=active]:border-foreground data-[state=active]:bg-transparent data-[state=active]:shadow-none text-xs font-medium h-10 px-3"
          >
            Dashboard
          </TabsTrigger>
          <TabsTrigger
            value="records"
            className="rounded-none border-b-2 border-transparent data-[state=active]:border-foreground data-[state=active]:bg-transparent data-[state=active]:shadow-none text-xs font-medium h-10 px-3"
          >
            Records
          </TabsTrigger>
          {!isArtist && (
            <TabsTrigger
              value="rules"
              className="rounded-none border-b-2 border-transparent data-[state=active]:border-foreground data-[state=active]:bg-transparent data-[state=active]:shadow-none text-xs font-medium h-10 px-3"
            >
              Rules
            </TabsTrigger>
          )}
          {!isArtist && canManage && (
            <TabsTrigger
              value="adjustments"
              className="rounded-none border-b-2 border-transparent data-[state=active]:border-foreground data-[state=active]:bg-transparent data-[state=active]:shadow-none text-xs font-medium h-10 px-3"
            >
              Adjustments
            </TabsTrigger>
          )}
          <TabsTrigger
            value="disputes"
            className="rounded-none border-b-2 border-transparent data-[state=active]:border-foreground data-[state=active]:bg-transparent data-[state=active]:shadow-none text-xs font-medium h-10 px-3 relative"
          >
            Disputes
            {!isArtist && openDisputeCount > 0 && (
              <span className="ml-1.5 inline-flex h-4 min-w-4 items-center justify-center rounded-full bg-amber-400/20 px-1 text-[10px] font-semibold text-amber-400 tabular-nums">
                {openDisputeCount > 99 ? '99+' : openDisputeCount}
              </span>
            )}
          </TabsTrigger>
        </TabsList>

        {/* ── Tab content ───────────────────────────────────────────────── */}
        <div className="flex-1 overflow-y-auto">
          <TabsContent value="dashboard" className="mt-0 h-full">
            <CommissionsDashboard
              from={from}
              to={to}
              isArtist={isArtist}
              canApprove={canApprove}
              canManage={canManage}
              isOwner={isOwner}
            />
          </TabsContent>

          <TabsContent value="records" className="mt-0">
            <RecordsTable
              from={from}
              to={to}
              isArtist={isArtist}
              canApprove={canApprove}
              canManage={canManage}
              isOwner={isOwner}
            />
          </TabsContent>

          {!isArtist && (
            <TabsContent value="rules" className="mt-0">
              <RulesList
                from={from}
                to={to}
                isArtist={false}
                canManage={canManage}
                isOwner={isOwner}
              />
            </TabsContent>
          )}

          {!isArtist && canManage && (
            <TabsContent value="adjustments" className="mt-0">
              <AdjustmentsList
                from={from}
                to={to}
                isArtist={false}
                canManage={canManage}
              />
            </TabsContent>
          )}

          <TabsContent value="disputes" className="mt-0">
            <DisputesList
              from={from}
              to={to}
              canResolve={canManage && !isArtist}
              isArtist={isArtist}
            />
          </TabsContent>
        </div>
      </Tabs>

      {/* ── Global modals (spawned from header Add button) ─────────────── */}
      <AdjustmentModal open={adjustmentOpen} onOpenChange={setAdjustmentOpen} record={null} />

      <RuleEditorDrawer
        open={ruleDrawerOpen}
        onOpenChange={setRuleDrawerOpen}
        rule={null}
        canManage={canManage}
      />
    </div>
  )
}

